static const char nx_str_1290[7289] = "// std.args: command-line argument parsing, written in Nexium.\n//\n// `import std.args` then:\n//\n//     var p = args.Parser.new(os.args())\n//     let verbose = p.flag(\"--verbose\", \"-v\")\n//     let level = p.option(\"--level\", \"-l\") orelse \"info\"\n//     let files = p.rest()\n//\n// Long options take `--name value` or `--name=value`; short ones `-n value`.\n// Everything after `--` is positional. Unknown options stay in `rest()`\n// so the caller can report them.\n\npub struct Parser {\n    argv: [][]u8\n    used: List(bool)\n}\n\nimpl Parser {\n    /// Wrap `os.args()`; the program name in `argv[0]` is skipped.\n    pub fn new(argv: [][]u8) -> Parser {\n        var used = List(bool).with_capacity(argv.len)\n        for _ in argv { used.append(false) }\n        if used.len > 0 { used[0] = true }\n        return Parser{ .argv = argv, .used = used }\n    }\n\n    fn matches(self: *Self, i: usize, long: []u8, short: []u8) -> bool {\n        let a = self.argv[i]\n        return a == long or (short.len > 0 and a == short)\n    }\n\n    /// True when the flag is present (any number of times).\n    pub fn flag(self: *mut Self, long: []u8, short: []u8) -> bool {\n        var found = false\n        for a, i in self.argv {\n            if a == \"--\" { break }\n            if self.matches(i, long, short) {\n                self.used[i] = true\n                found = true\n            }\n        }\n        return found\n    }\n\n    /// How many times the flag appears (`-vvv` counts as three).\n    pub fn count(self: *mut Self, long: []u8, short: []u8) -> usize {\n        var n: usize = 0\n        for a, i in self.argv {\n            if a == \"--\" { break }\n            if self.matches(i, long, short) {\n                self.used[i] = true\n                n += 1\n            } else if short.len == 2 and a.len > 2 and a[0] == '-' and a[1] != '-' {\n                // stacked short flags: -vvv\n                var all = true\n                for c in a[1..] { if c != short[1] { all = false } }\n                if all {\n                    self.used[i] = true\n                    n += a.len - 1\n                }\n            }\n        }\n        return n\n    }\n\n    /// The value of `--name value`, `--name=value`, or `-n value`; the last one wins.\n    pub fn option(self: *mut Self, long: []u8, short: []u8) -> ?[]u8 {\n        var value: ?[]u8 = null\n        for a, i in self.argv {\n            if a == \"--\" { break }\n            if self.matches(i, long, short) {\n                self.used[i] = true\n                if i + 1 < self.argv.len {\n                    self.used[i + 1] = true\n                    value = self.argv[i + 1]\n                }\n            } else if a.len > long.len and a.starts_with(long) and a[long.len] == '=' {\n                self.used[i] = true\n                value = a[long.len + 1..]\n            }\n        }\n        return value\n    }\n\n    /// Every value of a repeatable option, in order.\n    pub fn options(self: *mut Self, long: []u8, short: []u8) -> List([]u8) {\n        var out = List([]u8).new()\n        for a, i in self.argv {\n            if a == \"--\" { break }\n            if self.matches(i, long, short) {\n                self.used[i] = true\n                if i + 1 < self.argv.len {\n                    self.used[i + 1] = true\n                    out.append(self.argv[i + 1])\n                }\n            } else if a.len > long.len and a.starts_with(long) and a[long.len] == '=' {\n                self.used[i] = true\n                out.append(a[long.len + 1..])\n            }\n        }\n        return out\n    }\n\n    /// An option parsed as an integer; `error.InvalidInput` when present but not a number.\n    pub fn int_option(self: *mut Self, long: []u8, short: []u8) -> !?i64 {\n        let raw = self.option(long, short) orelse return null\n        let v = raw.parse_int(i64) catch |e| return error.InvalidInput\n        return v\n    }\n\n    /// Arguments not consumed by any query, plus everything after `--`.\n    pub fn rest(self: *Self) -> List([]u8) {\n        var out = List([]u8).new()\n        var after_dashes = false\n        for a, i in self.argv {\n            if after_dashes {\n                out.append(a)\n            } else if a == \"--\" {\n                after_dashes = true\n            } else if !self.used[i] {\n                out.append(a)\n            }\n        }\n        return out\n    }\n\n    /// Unconsumed arguments that look like options: the ones the program did not ask for.\n    pub fn unknown_options(self: *Self) -> List([]u8) {\n        var out = List([]u8).new()\n        for a, i in self.argv {\n            if a == \"--\" { break }\n            if !self.used[i] and a.len > 1 and a[0] == '-' { out.append(a) }\n        }\n        return out\n    }\n}\n\n/// Render a usage line and option table from (flags, description) rows.\npub fn usage(program: []u8, summary: []u8, rows: [][]u8) -> String {\n    var out = String.new()\n    out.append(\"usage: \")\n    out.append(program)\n    out.append(\" \")\n    out.append(summary)\n    out.append(\"\\n\")\n    var i: usize = 0\n    while i + 1 < rows.len {\n        out.append(\"  \")\n        out.append(rows[i])\n        for _ in rows[i].len..22 { out.push_byte(' ') }\n        out.append(rows[i + 1])\n        out.append(\"\\n\")\n        i += 2\n    }\n    return out\n}\n\n/// The environment as a map, from `os.environ()`.\npub fn env_map() -> Map(String, String) {\n    var m = Map(String, String).new()\n    for entry in os.environ() {\n        var i: usize = 0\n        while i < entry.len and entry[i] != '=' { i += 1 }\n        if i == 0 or i >= entry.len { continue }\n        m.put(String.from(entry[0..i]), String.from(entry[i + 1..entry.len]))\n    }\n    return m\n}\n\ntest \"env map\" {\n    let m = env_map()\n    expect(m.len > 0)\n}\n\ntest \"flags and options\" {\n    let argv = [\"prog\", \"-v\", \"--level\", \"debug\", \"--name=nx\", \"in.txt\", \"-v\", \"--\", \"-x\"]\n    var p = Parser.new(argv[..])\n    expect(p.flag(\"--verbose\", \"-v\"))\n    expect(!p.flag(\"--quiet\", \"-q\"))\n    expect_eq(p.option(\"--level\", \"-l\") orelse \"none\", \"debug\")\n    expect_eq(p.option(\"--name\", \"-n\") orelse \"none\", \"nx\")\n    expect(p.option(\"--missing\", \"\") == null)\n    let rest = p.rest()\n    expect_eq(rest.len, 2)\n    expect_eq(rest[0], \"in.txt\")\n    expect_eq(rest[1], \"-x\")\n}\n\ntest \"counts and repeats\" {\n    let argv = [\"prog\", \"-vvv\", \"-I\", \"a\", \"-I\", \"b\", \"--include=c\"]\n    var p = Parser.new(argv[..])\n    expect_eq(p.count(\"--verbose\", \"-v\"), 3)\n    let incs = p.options(\"--include\", \"-I\")\n    expect_eq(incs.len, 3)\n    expect_eq(incs[2], \"c\")\n    expect_eq(p.rest().len, 0)\n}\n\ntest \"integers and unknowns\" {\n    let argv = [\"prog\", \"--jobs\", \"8\", \"--bad\", \"--depth=x\"]\n    var p = Parser.new(argv[..])\n    let jobs = try p.int_option(\"--jobs\", \"-j\")\n    expect_eq(jobs orelse 0, 8)\n    let none = try p.int_option(\"--none\", \"\")\n    expect(none == null)\n    var bad = false\n    _ = p.int_option(\"--depth\", \"-d\") catch |e| {\n        bad = true\n        null\n    }\n    expect(bad)\n    let unk = p.unknown_options()\n    expect_eq(unk.len, 1)\n    expect_eq(unk[0], \"--bad\")\n}\n\ntest \"usage text\" {\n    let rows = [\"-v, --verbose\", \"say more\", \"-l, --level L\", \"log level\"]\n    let u = usage(\"tool\", \"[options] FILE\", rows[..])\n    expect(u.starts_with(\"usage: tool [options] FILE\\n\"))\n    expect(u.find(\"  -v, --verbose\") != null)\n    expect(u.find(\"log level\\n\") != null)\n}\n";
static const char nx_str_1291[6122] = "// std.bytes: encodings and byte-level utilities, written in Nexium.\n//\n// `import std.bytes` then `bytes.hex(data)`, `bytes.base64(data)`, ...\n// Decoders return `error.InvalidInput` on malformed text.\n\nconst HEX = \"0123456789abcdef\"\nconst B64 = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"\n\n/// Lower-case hexadecimal, two characters per byte.\npub fn hex(data: []u8) -> String {\n    var out = String.with_capacity(data.len * 2)\n    for b in data {\n        out.push_byte(HEX[(b >> 4) as usize])\n        out.push_byte(HEX[(b & 15) as usize])\n    }\n    return out\n}\n\nfn hex_value(c: u8) -> ?u8 {\n    if c >= '0' and c <= '9' { return c - '0' }\n    if c >= 'a' and c <= 'f' { return c - 'a' + 10 }\n    if c >= 'A' and c <= 'F' { return c - 'A' + 10 }\n    return null\n}\n\n/// Bytes from hexadecimal text (either case, even length).\npub fn unhex(text: []u8) -> !String {\n    if text.len % 2 != 0 { return error.InvalidInput }\n    var out = String.with_capacity(text.len / 2)\n    var i: usize = 0\n    while i < text.len {\n        let hi = hex_value(text[i]) orelse return error.InvalidInput\n        let lo = hex_value(text[i + 1]) orelse return error.InvalidInput\n        out.push_byte(hi * 16 + lo)\n        i += 2\n    }\n    return out\n}\n\n/// Standard base64 with `=` padding.\npub fn base64(data: []u8) -> String {\n    var out = String.with_capacity((data.len + 2) / 3 * 4)\n    var i: usize = 0\n    while i + 3 <= data.len {\n        let n = (data[i] as u32) << 16 | (data[i + 1] as u32) << 8 | data[i + 2] as u32\n        out.push_byte(B64[(n >> 18) as usize & 63])\n        out.push_byte(B64[(n >> 12) as usize & 63])\n        out.push_byte(B64[(n >> 6) as usize & 63])\n        out.push_byte(B64[n as usize & 63])\n        i += 3\n    }\n    let rest = data.len - i\n    if rest == 1 {\n        let n = (data[i] as u32) << 16\n        out.push_byte(B64[(n >> 18) as usize & 63])\n        out.push_byte(B64[(n >> 12) as usize & 63])\n        out.append(\"==\")\n    } else if rest == 2 {\n        let n = (data[i] as u32) << 16 | (data[i + 1] as u32) << 8\n        out.push_byte(B64[(n >> 18) as usize & 63])\n        out.push_byte(B64[(n >> 12) as usize & 63])\n        out.push_byte(B64[(n >> 6) as usize & 63])\n        out.append(\"=\")\n    }\n    return out\n}\n\nfn b64_value(c: u8) -> ?u32 {\n    if c >= 'A' and c <= 'Z' { return (c - 'A') as u32 }\n    if c >= 'a' and c <= 'z' { return (c - 'a') as u32 + 26 }\n    if c >= '0' and c <= '9' { return (c - '0') as u32 + 52 }\n    if c == '+' { return 62 }\n    if c == '/' { return 63 }\n    return null\n}\n\n/// Bytes from standard base64 (padding optional).\npub fn unbase64(text: []u8) -> !String {\n    var out = String.with_capacity(text.len / 4 * 3)\n    var acc: u32 = 0\n    var bits: u32 = 0\n    for c in text {\n        if c == '=' or c == '\\n' or c == '\\r' { continue }\n        let v = b64_value(c) orelse return error.InvalidInput\n        acc = (acc << 6) | v\n        bits += 6\n        if bits >= 8 {\n            bits -= 8\n            out.push_byte(((acc >> bits) & 255) as u8)\n        }\n    }\n    return out\n}\n\n/// FNV-1a, 32 bits: a fast non-cryptographic hash.\npub fn fnv1a(data: []u8) -> u32 {\n    var h: u32 = 2166136261\n    for b in data {\n        h ^= b as u32\n        h *%= 16777619\n    }\n    return h\n}\n\n/// CRC-32 (IEEE), as used by zip and PNG.\npub fn crc32(data: []u8) -> u32 {\n    var crc: u32 = 0xFFFFFFFF\n    for b in data {\n        crc ^= b as u32\n        for _ in 0..8 {\n            let mask = 0 -% (crc & 1)\n            crc = (crc >> 1) ^ (0xEDB88320 & mask)\n        }\n    }\n    return crc ^ 0xFFFFFFFF\n}\n\n/// Big-endian 32-bit read.\npub fn read_u32_be(data: []u8, at: usize) -> u32 {\n    return (data[at] as u32) << 24 | (data[at + 1] as u32) << 16 | (data[at + 2] as u32) << 8 | data[at + 3] as u32\n}\n\n/// Little-endian 32-bit read.\npub fn read_u32_le(data: []u8, at: usize) -> u32 {\n    return (data[at + 3] as u32) << 24 | (data[at + 2] as u32) << 16 | (data[at + 1] as u32) << 8 | data[at] as u32\n}\n\n/// Append a big-endian 32-bit value.\npub fn write_u32_be(out: *mut String, v: u32) {\n    out.push_byte((v >> 24) as u8)\n    out.push_byte(((v >> 16) & 255) as u8)\n    out.push_byte(((v >> 8) & 255) as u8)\n    out.push_byte((v & 255) as u8)\n}\n\n/// Append a little-endian 32-bit value.\npub fn write_u32_le(out: *mut String, v: u32) {\n    out.push_byte((v & 255) as u8)\n    out.push_byte(((v >> 8) & 255) as u8)\n    out.push_byte(((v >> 16) & 255) as u8)\n    out.push_byte((v >> 24) as u8)\n}\n\n/// Bytes that differ, for a compact diff of two buffers.\npub fn first_difference(a: []u8, b: []u8) -> ?usize {\n    let n = if a.len < b.len { a.len } else { b.len }\n    for i in 0..n { if a[i] != b[i] { return i } }\n    if a.len != b.len { return n }\n    return null\n}\n\ntest \"hex\" {\n    expect_eq(hex(\"AZ\"), \"415a\")\n    expect_eq(hex(\"\"), \"\")\n    let back = try unhex(\"415A\")\n    expect_eq(back, \"AZ\")\n    expect((unhex(\"41z\") catch |e| String.from(@errorName(e))) == \"InvalidInput\")\n    expect((unhex(\"4\") catch |e| String.from(@errorName(e))) == \"InvalidInput\")\n}\n\ntest \"base64 round trips\" {\n    expect_eq(base64(\"Man\"), \"TWFu\")\n    expect_eq(base64(\"Ma\"), \"TWE=\")\n    expect_eq(base64(\"M\"), \"TQ==\")\n    expect_eq(base64(\"\"), \"\")\n    expect_eq(base64(\"hello, nexium\"), \"aGVsbG8sIG5leGl1bQ==\")\n    let back = try unbase64(\"aGVsbG8sIG5leGl1bQ==\")\n    expect_eq(back, \"hello, nexium\")\n    let unpadded = try unbase64(\"TWE\")\n    expect_eq(unpadded, \"Ma\")\n    expect((unbase64(\"T*E=\") catch |e| String.from(@errorName(e))) == \"InvalidInput\")\n}\n\ntest \"hashes\" {\n    expect_eq(fnv1a(\"hello\"), 1335831723)\n    expect_eq(crc32(\"123456789\"), 0xCBF43926)\n    expect_eq(crc32(\"\"), 0)\n}\n\ntest \"integers in and out\" {\n    var buf = String.new()\n    write_u32_be(&mut buf, 0x01020304)\n    write_u32_le(&mut buf, 0x01020304)\n    expect_eq(buf.len, 8)\n    expect_eq(read_u32_be(buf, 0), 0x01020304)\n    expect_eq(read_u32_le(buf, 4), 0x01020304)\n    expect_eq(buf[4], 4)\n}\n\ntest \"first_difference\" {\n    expect_eq(first_difference(\"abc\", \"abd\") orelse 99, 2)\n    expect_eq(first_difference(\"abc\", \"abcd\") orelse 99, 3)\n    expect(first_difference(\"abc\", \"abc\") == null)\n}\n";
static const char nx_str_1292[3] = "fs";
static const char nx_str_1293[11537] = "// std.fs: files, directories and paths, written in Nexium.\n//\n// `import std.fs` then:\n//\n//     if fs.exists(\"notes.txt\") { ... }\n//     try fs.make_dirs(\"out/logs\")\n//     for name in try fs.list(\"out\") { ... }\n//     for path in try fs.walk(\"src\") { ... }        // every file, recursively\n//     let cfg = fs.join(fs.parent(argv0), \"app.toml\")\n//\n// The platform calls are the `io.*` builtins (documented in the language\n// reference); this module adds paths, sorted listings, recursive create and\n// remove, and a walker. Paths are byte strings; `/` and `\\` both separate\n// components on every platform, and results use `/` unless the input used `\\`.\n\n// ------------------------------------------------------------------ queries\n\n/// Is there a file or directory at `path`?\npub fn exists(path: []u8) -> bool {\n    return io.file_kind(path) != 0\n}\n\n/// Is `path` an existing regular file (anything that is not a directory)?\npub fn is_file(path: []u8) -> bool {\n    return io.file_kind(path) == 1\n}\n\n/// Is `path` an existing directory?\npub fn is_dir(path: []u8) -> bool {\n    return io.file_kind(path) == 2\n}\n\n/// The size of a file in bytes.\npub fn size(path: []u8) -> !u64 {\n    return io.file_size(path)\n}\n\n/// The modification time in milliseconds since the epoch.\npub fn modified(path: []u8) -> !i64 {\n    return io.file_modified(path)\n}\n\n// ------------------------------------------------------------------ contents\n\n/// The whole file as a String.\npub fn read(path: []u8) -> !String {\n    return io.read_file(path)\n}\n\n/// The lines of a file, without their line endings.\npub fn read_lines(path: []u8) -> !List(String) {\n    let text = try io.read_file(path)\n    var out = List(String).new()\n    for l in text.lines() { out.append(String.from(l)) }\n    return out\n}\n\n/// Write (replace) a file.\npub fn write(path: []u8, data: []u8) -> !void {\n    return io.write_file(path, data)\n}\n\n/// Append to a file, creating it when missing.\npub fn append(path: []u8, data: []u8) -> !void {\n    return io.append_file(path, data)\n}\n\n/// Copy a file's contents to a new path (the destination is replaced).\npub fn copy(from: []u8, to: []u8) -> !void {\n    let data = try io.read_file(from)\n    return io.write_file(to, data)\n}\n\n// ------------------------------------------------------------------ directories\n\n/// The names in a directory, sorted, without `.` and `..`.\npub fn list(path: []u8) -> !List(String) {\n    var names = try io.list_dir(path)\n    sort_names(&mut names)\n    return names\n}\n\n/// Create one directory; fine when it already exists.\npub fn make_dir(path: []u8) -> !void {\n    return io.make_dir(path)\n}\n\n/// Create a directory and every missing parent.\npub fn make_dirs(path: []u8) -> !void {\n    if path.len == 0 or is_dir(path) { return }\n    let p = parent(path)\n    if p.len > 0 and p.len < path.len and !is_dir(p) { try make_dirs(p) }\n    return io.make_dir(path)\n}\n\n/// Remove a file or an empty directory.\npub fn remove(path: []u8) -> !void {\n    if is_dir(path) { return io.remove_dir(path) }\n    return io.remove_file(path)\n}\n\n/// Remove a file, or a directory with everything in it.\npub fn remove_all(path: []u8) -> !void {\n    if is_dir(path) {\n        let names = try io.list_dir(path)\n        for n in names {\n            let child = join(path, n)\n            try remove_all(child)\n        }\n        return io.remove_dir(path)\n    }\n    if exists(path) { return io.remove_file(path) }\n}\n\n/// Rename or move a file or directory (an existing destination file is replaced).\npub fn rename(from: []u8, to: []u8) -> !void {\n    return io.rename(from, to)\n}\n\n/// Every file under `root`, recursively, as paths joined onto `root`, sorted\n/// directory by directory. Directories themselves are not listed.\npub fn walk(root: []u8) -> !List(String) {\n    var out = List(String).new()\n    try walk_into(root, &mut out)\n    return out\n}\n\nfn walk_into(dir: []u8, out: *mut List(String)) -> !void {\n    let names = try list(dir)\n    for n in names {\n        let child = join(dir, n)\n        if is_dir(child) {\n            try walk_into(child, out)\n        } else {\n            out.append(child)\n        }\n    }\n}\n\n/// The current working directory.\npub fn cwd() -> !String {\n    return io.cwd()\n}\n\n/// The directory for temporary files.\npub fn temp_dir() -> String {\n    return io.temp_dir()\n}\n\n/// A fresh path in the temporary directory, `<temp>/<prefix><number>`, that\n/// does not exist yet. The caller creates it.\npub fn temp_path(prefix: []u8) -> String {\n    let base = io.temp_dir()\n    var n = time.now()\n    while true {\n        var candidate = join(base, prefix)\n        candidate.append(format(\"{}\", .{n}))\n        if !exists(candidate) { return candidate }\n        n += 1\n    }\n}\n\n// ------------------------------------------------------------------ paths\n\nfn is_sep(c: u8) -> bool {\n    return c == '/' or c == '\\\\'\n}\n\n/// The separator a path uses: `\\` when it contains one, else `/`.\nfn sep_of(path: []u8) -> u8 {\n    for c in path { if c == '\\\\' { return '\\\\' } }\n    return '/'\n}\n\n/// Does the path start at a root (`/x`, `C:\\x`, `C:/x`, `\\\\server`)?\npub fn is_absolute(path: []u8) -> bool {\n    if path.len == 0 { return false }\n    if is_sep(path[0]) { return true }\n    return path.len >= 3 and path[1] == ':' and is_sep(path[2])\n}\n\n/// `dir/name`; a separator is added only when needed, and an absolute `name`\n/// replaces `dir`.\npub fn join(dir: []u8, name: []u8) -> String {\n    if dir.len == 0 or is_absolute(name) { return String.from(name) }\n    var out = String.from(dir)\n    if name.len == 0 { return out }\n    if !is_sep(dir[dir.len - 1]) { out.push_byte(sep_of(dir)) }\n    out.append(name)\n    return out\n}\n\n/// Everything before the last separator: `a/b/c.txt` -> `a/b`, `c.txt` -> ``,\n/// `/c.txt` -> `/`.\npub fn parent(path: []u8) -> []u8 {\n    var end = path.len\n    while end > 0 and is_sep(path[end - 1]) { end -= 1 }\n    var i = end\n    while i > 0 and !is_sep(path[i - 1]) { i -= 1 }\n    if i == 0 { return path[0..0] }\n    var j = i\n    while j > 1 and is_sep(path[j - 1]) { j -= 1 }\n    if j == 1 and is_sep(path[0]) { return path[0..1] }\n    if j >= 2 and path[j - 1] == ':' { return path[0..j + 1] }\n    return path[0..j]\n}\n\n/// The last component: `a/b/c.txt` -> `c.txt`.\npub fn base_name(path: []u8) -> []u8 {\n    var end = path.len\n    while end > 0 and is_sep(path[end - 1]) { end -= 1 }\n    var i = end\n    while i > 0 and !is_sep(path[i - 1]) { i -= 1 }\n    return path[i..end]\n}\n\n/// The extension without the dot: `a/b.tar.gz` -> `gz`, `Makefile` -> ``.\npub fn extension(path: []u8) -> []u8 {\n    let name = base_name(path)\n    var i = name.len\n    while i > 0 {\n        i -= 1\n        if name[i] == '.' {\n            if i == 0 { return name[0..0] }\n            return name[i + 1..name.len]\n        }\n    }\n    return name[0..0]\n}\n\n/// The base name without its extension: `a/b.tar.gz` -> `b.tar`.\npub fn stem(path: []u8) -> []u8 {\n    let name = base_name(path)\n    var i = name.len\n    while i > 0 {\n        i -= 1\n        if name[i] == '.' {\n            if i == 0 { return name }\n            return name[0..i]\n        }\n    }\n    return name\n}\n\n/// The path with its extension replaced (or added): `a/b.txt`, `md` -> `a/b.md`.\npub fn with_extension(path: []u8, ext: []u8) -> String {\n    let e = extension(path)\n    var out = String.from(if e.len > 0 { path[0..path.len - e.len - 1] } else { path })\n    if ext.len > 0 {\n        out.push_byte('.')\n        out.append(ext)\n    }\n    return out\n}\n\n/// Collapse `.` and `..` components and repeated separators:\n/// `a/./b/../c//d` -> `a/c/d`. A leading `..` is kept.\npub fn normalize(path: []u8) -> String {\n    let sep = sep_of(path)\n    var parts = List([]u8).new()\n    var start: usize = 0\n    var i: usize = 0\n    while i <= path.len {\n        if i == path.len or is_sep(path[i]) {\n            let part = path[start..i]\n            if part.len == 0 or part == \".\" {\n                // skip\n            } else if part == \"..\" {\n                if parts.len > 0 and parts[parts.len - 1] != \"..\" { _ = parts.pop() }\n                else if ! (path.len > 0 and is_sep(path[0])) { parts.append(part) }\n            } else {\n                parts.append(part)\n            }\n            start = i + 1\n        }\n        i += 1\n    }\n    var out = String.new()\n    if path.len > 0 and is_sep(path[0]) { out.push_byte(sep) }\n    for p, k in parts {\n        if k > 0 { out.push_byte(sep) }\n        out.append(p)\n    }\n    if out.len == 0 { out.push_byte('.') }\n    return out\n}\n\n// ------------------------------------------------------------------ helpers\n\nfn less(a: []u8, b: []u8) -> bool {\n    var i: usize = 0\n    while i < a.len and i < b.len {\n        if a[i] != b[i] { return a[i] < b[i] }\n        i += 1\n    }\n    return a.len < b.len\n}\n\nfn sort_names(names: *mut List(String)) {\n    var i: usize = 1\n    while i < names.len {\n        var j = i\n        while j > 0 and less(names[j], names[j - 1]) {\n            let s = names.remove(j)\n            names.insert(j - 1, s)\n            j -= 1\n        }\n        i += 1\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"path parts\" {\n    expect_eq(parent(\"a/b/c.txt\"), \"a/b\")\n    expect_eq(parent(\"c.txt\"), \"\")\n    expect_eq(parent(\"/c.txt\"), \"/\")\n    expect_eq(parent(\"a/b/\"), \"a\")\n    expect_eq(parent(\"C:\\\\x\\\\y.txt\"), \"C:\\\\x\")\n    expect_eq(parent(\"C:\\\\y.txt\"), \"C:\\\\\")\n    expect_eq(base_name(\"a/b/c.txt\"), \"c.txt\")\n    expect_eq(base_name(\"a/b/\"), \"b\")\n    expect_eq(extension(\"a/b.tar.gz\"), \"gz\")\n    expect_eq(extension(\"Makefile\"), \"\")\n    expect_eq(extension(\".bashrc\"), \"\")\n    expect_eq(stem(\"a/b.tar.gz\"), \"b.tar\")\n    expect_eq(stem(\".bashrc\"), \".bashrc\")\n    expect_eq(with_extension(\"a/b.txt\", \"md\"), \"a/b.md\")\n    expect_eq(with_extension(\"a/b\", \"md\"), \"a/b.md\")\n    expect_eq(with_extension(\"a/b.txt\", \"\"), \"a/b\")\n}\n\ntest \"join and absolute\" {\n    expect_eq(join(\"a\", \"b\"), \"a/b\")\n    expect_eq(join(\"a/\", \"b\"), \"a/b\")\n    expect_eq(join(\"\", \"b\"), \"b\")\n    expect_eq(join(\"a\", \"/b\"), \"/b\")\n    expect_eq(join(\"C:\\\\x\", \"y\"), \"C:\\\\x\\\\y\")\n    expect(is_absolute(\"/x\"))\n    expect(is_absolute(\"C:\\\\x\"))\n    expect(is_absolute(\"C:/x\"))\n    expect(!is_absolute(\"x/y\"))\n    expect(!is_absolute(\"\"))\n}\n\ntest \"normalize\" {\n    expect_eq(normalize(\"a/./b/../c//d\"), \"a/c/d\")\n    expect_eq(normalize(\"/a/../..\"), \"/\")\n    expect_eq(normalize(\"../a\"), \"../a\")\n    expect_eq(normalize(\"a/..\"), \".\")\n    expect_eq(normalize(\"C:\\\\a\\\\..\\\\b\"), \"C:\\\\b\")\n}\n\ntest \"files and directories\" {\n    let root = temp_path(\"nxfs-\")\n    try make_dirs(join(root, \"deep/er\"))\n    expect(is_dir(root))\n    expect(is_dir(join(root, \"deep/er\")))\n    let f = join(root, \"deep/er/note.txt\")\n    try write(f, \"one\\ntwo\\n\")\n    try append(f, \"three\\n\")\n    expect(is_file(f))\n    expect(!is_dir(f))\n    expect_eq(try size(f), 14)\n    let lines = try read_lines(f)\n    expect_eq(lines.len, 3)\n    expect_eq(lines[2], \"three\")\n    try copy(f, join(root, \"copy.txt\"))\n    let names = try list(root)\n    expect_eq(names.len, 2)\n    expect_eq(names[0], \"copy.txt\")\n    expect_eq(names[1], \"deep\")\n    let files = try walk(root)\n    expect_eq(files.len, 2)\n    expect_eq(base_name(files[1]), \"note.txt\")\n    try rename(join(root, \"copy.txt\"), join(root, \"moved.txt\"))\n    expect(!exists(join(root, \"copy.txt\")))\n    expect(exists(join(root, \"moved.txt\")))\n    var missing = false\n    _ = size(\"definitely/missing\") catch |e| {\n        missing = e == error.NotFound\n        0\n    }\n    expect(missing)\n    try remove_all(root)\n    expect(!exists(root))\n}\n";
static const char nx_str_1294[5] = "http";
static const char nx_str_1295[21319] = "// std.http: an HTTP/1.1 client and a small server, written in Nexium over\n// std.net and std.stream.\n//\n// `import std.http` then:\n//\n//     let r = try http.get(\"http://example.com/\")\n//     println(\"{} {}\", .{r.status, r.body.len})\n//     if let ct = r.header(\"content-type\") { ... }\n//\n//     fn hello(req: *http.Request) -> http.Response {\n//         return http.text(200, \"hello from Nexium\")\n//     }\n//     var router = http.Router.new()\n//     router.get(\"/\", hello)\n//     var server = try http.Server.bind(\"127.0.0.1\", 8080)\n//     try server.serve(&router)                  // forever, one request at a time\n//\n// The client speaks HTTP/1.1 with `Connection: close`, reads bodies by\n// Content-Length, chunked encoding, or until close, and follows up to five\n// redirects. Plain `http://` only; TLS needs a C library through `@cImport`.\n// The server handles one connection at a time, which is what a tool, a\n// local dashboard or a test needs; threads come later in the roadmap.\n\nimport std.net\nimport std.stream\nimport std.fs\n\nconst MAX_REDIRECTS: usize = 5\nconst MAX_HEADER_LINES: usize = 200\n\npub struct Header {\n    name: String\n    value: String\n}\n\nfn header_value(headers: *List(Header), name: []u8) -> ?[]u8 {\n    for i in 0..headers.len {\n        if headers[i].name.eq_ignore_case(name) { return headers[i].value }\n    }\n    return null\n}\n\nfn find_header(headers: *List(Header), name: []u8) -> ?usize {\n    for h, i in headers {\n        if h.name.eq_ignore_case(name) { return i }\n    }\n    return null\n}\n\n// ------------------------------------------------------------------ URLs\n\npub struct Url {\n    scheme: String\n    host: String\n    port: u16\n    /// path with the query, e.g. `/a/b?x=1`; never empty\n    path: String\n}\n\n/// Parse `http://host[:port][/path]`; null for anything else.\npub fn parse_url(s: []u8) -> ?Url {\n    var rest = s\n    var scheme = \"http\"\n    if rest.starts_with(\"http://\") {\n        rest = rest[7..rest.len]\n    } else if rest.starts_with(\"https://\") {\n        scheme = \"https\"\n        rest = rest[8..rest.len]\n    } else {\n        return null\n    }\n    var end: usize = 0\n    while end < rest.len and rest[end] != '/' and rest[end] != '?' { end += 1 }\n    let hostport = rest[0..end]\n    var path = rest[end..rest.len]\n    // the host is copied out: `a` owns its text only until the `if let` ends\n    var host = String.from(hostport)\n    var port: u16 = if scheme == \"https\" { 443 } else { 80 }\n    if let a = net.parse_addr(hostport) {\n        host = a.host.clone()\n        port = a.port\n    }\n    if host.len == 0 { return null }\n    var p = String.new()\n    if path.len == 0 or path[0] == '?' { p.append(\"/\") }\n    p.append(path)\n    return Url{ .scheme = String.from(scheme), .host = host, .port = port, .path = p }\n}\n\n// ------------------------------------------------------------------ responses\n\npub struct Response {\n    status: u16\n    reason: String\n    headers: List(Header)\n    body: String\n}\n\nimpl Response {\n    /// A header value, case-insensitive; null when absent.\n    pub fn header(self: *Self, name: []u8) -> ?[]u8 {\n        return header_value(&self.headers, name)\n    }\n\n    /// Add or replace a header (builder style).\n    pub fn with_header(self: *mut Self, name: []u8, value: []u8) {\n        if let i = find_header(&self.headers, name) {\n            self.headers[i].value = String.from(value)\n            return\n        }\n        self.headers.append(Header{ .name = String.from(name), .value = String.from(value) })\n    }\n\n    pub fn ok(self: *Self) -> bool {\n        return self.status >= 200 and self.status < 300\n    }\n}\n\n/// The standard reason phrase for a status.\npub fn reason_for(status: u16) -> []u8 {\n    if status == 200 { return \"OK\" }\n    if status == 201 { return \"Created\" }\n    if status == 204 { return \"No Content\" }\n    if status == 301 { return \"Moved Permanently\" }\n    if status == 302 { return \"Found\" }\n    if status == 304 { return \"Not Modified\" }\n    if status == 400 { return \"Bad Request\" }\n    if status == 401 { return \"Unauthorized\" }\n    if status == 403 { return \"Forbidden\" }\n    if status == 404 { return \"Not Found\" }\n    if status == 405 { return \"Method Not Allowed\" }\n    if status == 500 { return \"Internal Server Error\" }\n    return \"Unknown\"\n}\n\n/// A response with a body and a content type.\npub fn respond(status: u16, content_type: []u8, body: []u8) -> Response {\n    var headers = List(Header).new()\n    headers.append(Header{ .name = String.from(\"Content-Type\"), .value = String.from(content_type) })\n    return Response{ .status = status, .reason = String.from(reason_for(status)), .headers = headers, .body = String.from(body) }\n}\n\npub fn text(status: u16, body: []u8) -> Response {\n    return respond(status, \"text/plain; charset=utf-8\", body)\n}\n\npub fn html(status: u16, body: []u8) -> Response {\n    return respond(status, \"text/html; charset=utf-8\", body)\n}\n\npub fn json(status: u16, body: []u8) -> Response {\n    return respond(status, \"application/json\", body)\n}\n\npub fn not_found() -> Response {\n    return text(404, \"not found\\n\")\n}\n\n/// A redirect to `location`.\npub fn redirect(location: []u8) -> Response {\n    var r = text(302, \"\")\n    r.with_header(\"Location\", location)\n    return r\n}\n\n/// The content type for a file name, by extension.\npub fn content_type_for(path: []u8) -> []u8 {\n    let ext = fs.extension(path)\n    if ext == \"html\" or ext == \"htm\" { return \"text/html; charset=utf-8\" }\n    if ext == \"css\" { return \"text/css\" }\n    if ext == \"js\" { return \"text/javascript\" }\n    if ext == \"json\" { return \"application/json\" }\n    if ext == \"txt\" or ext == \"md\" or ext == \"nx\" { return \"text/plain; charset=utf-8\" }\n    if ext == \"png\" { return \"image/png\" }\n    if ext == \"jpg\" or ext == \"jpeg\" { return \"image/jpeg\" }\n    if ext == \"gif\" { return \"image/gif\" }\n    if ext == \"svg\" { return \"image/svg+xml\" }\n    if ext == \"ico\" { return \"image/x-icon\" }\n    if ext == \"pdf\" { return \"application/pdf\" }\n    return \"application/octet-stream\"\n}\n\n// ------------------------------------------------------------------ wire format\n\nfn parse_status(line: []u8) -> ?(u16, []u8) {\n    // HTTP/1.1 200 OK\n    if !line.starts_with(\"HTTP/\") { return null }\n    var i: usize = 0\n    while i < line.len and line[i] != ' ' { i += 1 }\n    if i + 4 > line.len { return null }\n    let status = line[i + 1..i + 4].parse_int(u16) catch return null\n    var reason = line[0..0]\n    if i + 5 <= line.len { reason = line[i + 5..line.len] }\n    return (status, reason)\n}\n\nfn read_headers(r: *mut stream.Reader) -> !List(Header) {\n    var headers = List(Header).new()\n    var n: usize = 0\n    while true {\n        let line = (try r.read_line()) orelse break\n        if line.len == 0 { break }\n        n += 1\n        if n > MAX_HEADER_LINES { return error.InvalidInput }\n        var c: usize = 0\n        while c < line.len and line[c] != ':' { c += 1 }\n        if c == line.len { return error.InvalidInput }\n        headers.append(Header{ .name = String.from(line[0..c]), .value = String.from(line[c + 1..line.len].trim()) })\n    }\n    return headers\n}\n\nfn hex_value(s: []u8) -> ?usize {\n    var v: usize = 0\n    var any = false\n    for c in s {\n        var d: usize = 0\n        if c >= '0' and c <= '9' { d = (c - '0') as usize }\n        else if c >= 'a' and c <= 'f' { d = (c - 'a' + 10) as usize }\n        else if c >= 'A' and c <= 'F' { d = (c - 'A' + 10) as usize }\n        else if c == ';' or c == ' ' { break }\n        else { return null }\n        v = v * 16 + d\n        any = true\n    }\n    return if any { v } else { null }\n}\n\nfn read_exact(r: *mut stream.Reader, n: usize) -> !String {\n    var out = String.with_capacity(n)\n    while out.len < n {\n        let chunk = try r.read(n - out.len)\n        if chunk.len == 0 { return error.Truncated }\n        out.append(chunk)\n    }\n    return out\n}\n\nfn read_body(r: *mut stream.Reader, headers: *List(Header), allow_until_close: bool) -> !String {\n    if let te = header_value(headers, \"transfer-encoding\") {\n        if te.eq_ignore_case(\"chunked\") {\n            var body = String.new()\n            while true {\n                let size_line = (try r.read_line()) orelse return error.Truncated\n                let size = hex_value(size_line) orelse return error.InvalidInput\n                if size == 0 {\n                    // trailers, then the blank line\n                    while true {\n                        let t = (try r.read_line()) orelse break\n                        if t.len == 0 { break }\n                    }\n                    break\n                }\n                body.append(try read_exact(r, size))\n                _ = try r.read_line()\n            }\n            return body\n        }\n    }\n    if let cl = header_value(headers, \"content-length\") {\n        let n = cl.parse_int(usize) catch return error.InvalidInput\n        return read_exact(r, n)\n    }\n    if allow_until_close { return r.read_all() }\n    return String.new()\n}\n\n/// Read a full response from a reader over the connection.\npub fn read_response(r: *mut stream.Reader) -> !Response {\n    let line = (try r.read_line()) orelse return error.Truncated\n    let st = parse_status(line) orelse return error.InvalidInput\n    let headers = try read_headers(r)\n    let body = if st.0 == 204 or st.0 == 304 { String.new() } else { try read_body(r, &headers, true) }\n    return Response{ .status = st.0, .reason = String.from(st.1), .headers = headers, .body = body }\n}\n\n/// Write a request; `headers` may add or override the defaults.\npub fn send_request(w: *mut stream.Writer, method: []u8, url: *Url, headers: *List(Header), body: []u8) -> !void {\n    try w.write(method)\n    try w.write(\" \")\n    try w.write(url.path)\n    try w.write(\" HTTP/1.1\\r\\nHost: \")\n    try w.write(url.host)\n    if url.port != 80 { try w.write(format(\":{}\", .{url.port})) }\n    try w.write(\"\\r\\n\")\n    if header_value(headers, \"user-agent\") == null { try w.write(\"User-Agent: nexium-http/0.3\\r\\n\") }\n    if header_value(headers, \"accept\") == null { try w.write(\"Accept: */*\\r\\n\") }\n    try w.write(\"Connection: close\\r\\n\")\n    if body.len > 0 or method == \"POST\" or method == \"PUT\" { try w.write(format(\"Content-Length: {}\\r\\n\", .{body.len})) }\n    for h in headers {\n        try w.write(h.name)\n        try w.write(\": \")\n        try w.write(h.value)\n        try w.write(\"\\r\\n\")\n    }\n    try w.write(\"\\r\\n\")\n    try w.write(body)\n    return w.flush()\n}\n\n// ------------------------------------------------------------------ client\n\nfn one_request(method: []u8, url: *Url, headers: *List(Header), body: []u8, timeout_ms: i64) -> !Response {\n    var conn = try net.TcpStream.connect_timeout(url.host, url.port, timeout_ms)\n    conn.set_timeout(timeout_ms)\n    var w = conn.writer()\n    send_request(&mut w, method, url, headers, body) catch |e| {\n        conn.close()\n        return e\n    }\n    var r = conn.reader()\n    let resp = read_response(&mut r)\n    conn.close()\n    return resp\n}\n\n/// Perform a request, following redirects. `error.InvalidInput` for a URL\n/// this client cannot speak (including `https://`).\npub fn request(method: []u8, url_text: []u8, headers: *List(Header), body: []u8) -> !Response {\n    var url = parse_url(url_text) orelse return error.InvalidInput\n    if url.scheme != \"http\" { return error.InvalidInput }\n    var hops: usize = 0\n    while true {\n        let resp = try one_request(method, &url, headers, body, 15000)\n        let is_redirect = resp.status == 301 or resp.status == 302 or resp.status == 303 or resp.status == 307 or resp.status == 308\n        if !is_redirect or hops >= MAX_REDIRECTS { return resp }\n        let loc = resp.header(\"location\") orelse return resp\n        hops += 1\n        if loc.starts_with(\"http://\") or loc.starts_with(\"https://\") {\n            url = parse_url(loc) orelse return error.InvalidInput\n            if url.scheme != \"http\" { return error.InvalidInput }\n        } else {\n            url.path = String.from(loc)\n        }\n    }\n}\n\npub fn get(url: []u8) -> !Response {\n    let none = List(Header).new()\n    return request(\"GET\", url, &none, \"\")\n}\n\npub fn post(url: []u8, content_type: []u8, body: []u8) -> !Response {\n    var headers = List(Header).new()\n    headers.append(Header{ .name = String.from(\"Content-Type\"), .value = String.from(content_type) })\n    return request(\"POST\", url, &headers, body)\n}\n\n// ------------------------------------------------------------------ server\n\npub struct Request {\n    method: String\n    /// the path without the query\n    path: String\n    /// the query string after `?`, without it\n    query: String\n    headers: List(Header)\n    body: String\n    peer: String\n}\n\nimpl Request {\n    pub fn header(self: *Self, name: []u8) -> ?[]u8 {\n        return header_value(&self.headers, name)\n    }\n\n    /// The value of a query parameter (`?a=1&b=2`), not decoded.\n    pub fn param(self: *Self, name: []u8) -> ?[]u8 {\n        for pair in self.query.split(\"&\") {\n            var eq: usize = 0\n            while eq < pair.len and pair[eq] != '=' { eq += 1 }\n            if pair[0..eq] == name { return if eq < pair.len { pair[eq + 1..pair.len] } else { pair[0..0] } }\n        }\n        return null\n    }\n}\n\n/// Read a request from a reader over the connection; null when the\n/// connection was closed before a request line.\npub fn read_request(r: *mut stream.Reader, peer: []u8) -> !?Request {\n    let line = (try r.read_line()) orelse return null\n    // GET /path?query HTTP/1.1\n    var a: usize = 0\n    while a < line.len and line[a] != ' ' { a += 1 }\n    if a == line.len { return error.InvalidInput }\n    var b = a + 1\n    while b < line.len and line[b] != ' ' { b += 1 }\n    let target = line[a + 1..b]\n    var q: usize = 0\n    while q < target.len and target[q] != '?' { q += 1 }\n    let headers = try read_headers(r)\n    let body = try read_body(r, &headers, false)\n    return Request{\n        .method = String.from(line[0..a]),\n        .path = String.from(target[0..q]),\n        .query = String.from(if q < target.len { target[q + 1..target.len] } else { target[0..0] }),\n        .headers = headers,\n        .body = body,\n        .peer = String.from(peer),\n    }\n}\n\n/// Write a response with `Content-Length` and `Connection: close`.\npub fn write_response(w: *mut stream.Writer, resp: *Response) -> !void {\n    try w.write(format(\"HTTP/1.1 {} \", .{resp.status}))\n    try w.write(resp.reason)\n    try w.write(\"\\r\\n\")\n    for h in resp.headers {\n        try w.write(h.name)\n        try w.write(\": \")\n        try w.write(h.value)\n        try w.write(\"\\r\\n\")\n    }\n    try w.write(format(\"Content-Length: {}\\r\\nConnection: close\\r\\n\\r\\n\", .{resp.body.len}))\n    try w.write(resp.body)\n    return w.flush()\n}\n\npub struct Route {\n    method: String\n    path: String\n    handler: fn(*Request) -> Response\n}\n\n/// Matches requests by method and exact path; a path ending in `/*`\n/// matches any request under that prefix.\npub struct Router {\n    routes: List(Route)\n    static_root: ?String\n}\n\nimpl Router {\n    pub fn new() -> Router {\n        return Router{ .routes = List(Route).new(), .static_root = null }\n    }\n\n    pub fn route(self: *mut Self, method: []u8, path: []u8, handler: fn(*Request) -> Response) {\n        self.routes.append(Route{ .method = String.from(method), .path = String.from(path), .handler = handler })\n    }\n\n    pub fn get(self: *mut Self, path: []u8, handler: fn(*Request) -> Response) {\n        self.route(\"GET\", path, handler)\n    }\n\n    pub fn post(self: *mut Self, path: []u8, handler: fn(*Request) -> Response) {\n        self.route(\"POST\", path, handler)\n    }\n\n    /// Serve files under `root` for paths no route claims.\n    pub fn serve_static(self: *mut Self, root: []u8) {\n        self.static_root = String.from(root)\n    }\n\n    /// The response for a request.\n    pub fn handle(self: *Self, req: *Request) -> Response {\n        for r in self.routes {\n            if r.method != req.method { continue }\n            let hit = if r.path.ends_with(\"/*\") { req.path.starts_with(r.path[0..r.path.len - 1]) } else { r.path == req.path }\n            if hit {\n                let h = r.handler\n                return h(req)\n            }\n        }\n        if let root = self.static_root {\n            if req.method == \"GET\" { return static_file(root, req.path) }\n        }\n        return not_found()\n    }\n}\n\n/// A file under `root` for a request path, refusing `..`; `index.html` for\n/// directories.\npub fn static_file(root: []u8, path: []u8) -> Response {\n    if path.find(\"..\") != null { return text(403, \"forbidden\\n\") }\n    var file = fs.join(root, if path.len > 0 and path[0] == '/' { path[1..path.len] } else { path })\n    if fs.is_dir(file) { file = fs.join(file, \"index.html\") }\n    if !fs.is_file(file) { return not_found() }\n    let data = fs.read(file) catch return text(500, \"cannot read file\\n\")\n    return respond(200, content_type_for(file), data)\n}\n\npub struct Server {\n    listener: net.TcpListener\n}\n\nimpl Server {\n    pub fn bind(host: []u8, port: u16) -> !Server {\n        return Server{ .listener = try net.TcpListener.bind(host, port) }\n    }\n\n    pub fn port(self: *Self) -> !u16 {\n        return self.listener.port()\n    }\n\n    /// Accept one connection, answer one request, close. `error.Timeout`\n    /// when nobody connects within `timeout_ms` (0 waits forever).\n    pub fn serve_one(self: *Self, router: *Router, timeout_ms: i64) -> !void {\n        var conn = try self.listener.accept_timeout(timeout_ms)\n        conn.set_timeout(10000)\n        let peer = conn.peer() catch String.from(\"?\")\n        var r = conn.reader()\n        var bad = false\n        let maybe = read_request(&mut r, peer) catch |_| {\n            bad = true\n            null\n        }\n        var resp = text(400, \"bad request\\n\")\n        if !bad {\n            if let req = maybe {\n                resp = router.handle(&req)\n            } else {\n                conn.close()\n                return\n            }\n        }\n        var w = conn.writer()\n        write_response(&mut w, &resp) catch { }\n        conn.close()\n    }\n\n    /// Serve forever, one request at a time.\n    pub fn serve(self: *Self, router: *Router) -> !void {\n        while true {\n            self.serve_one(router, 0) catch |e| {\n                if e != error.Timeout { return e }\n            }\n        }\n    }\n\n    pub fn close(self: *mut Self) {\n        self.listener.close()\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\nfn hello(req: *Request) -> Response {\n    var body = String.from(\"hello \")\n    body.append(req.param(\"name\") orelse \"world\")\n    return text(200, body)\n}\n\nfn echo(req: *Request) -> Response {\n    return respond(201, \"application/octet-stream\", req.body)\n}\n\ntest \"urls\" {\n    let u = parse_url(\"http://example.com/a/b?x=1\").?\n    expect_eq(u.host, \"example.com\")\n    expect_eq(u.port, 80)\n    expect_eq(u.path, \"/a/b?x=1\")\n    let p = parse_url(\"http://localhost:8080\").?\n    expect_eq(p.port, 8080)\n    expect_eq(p.path, \"/\")\n    expect(parse_url(\"ftp://x\") == null)\n    expect_eq(parse_url(\"https://h/\").?.port, 443)\n    expect_eq(content_type_for(\"a/b.css\"), \"text/css\")\n    expect_eq(hex_value(\"1A;ext\").?, 26)\n}\n\ntest \"request and response over loopback\" {\n    var router = Router.new()\n    router.get(\"/hello\", hello)\n    router.post(\"/echo\", echo)\n    var server = try Server.bind(\"127.0.0.1\", 0)\n    let port = try server.port()\n    var url = parse_url(format(\"http://127.0.0.1:{}/hello?name=nx\", .{port})).?\n\n    // the client sends first; the request fits the socket buffer, so the\n    // single-threaded server can then accept and answer it\n    var c = try net.TcpStream.connect_timeout(\"127.0.0.1\", port, 5000)\n    c.set_timeout(5000)\n    var w = c.writer()\n    let none = List(Header).new()\n    try send_request(&mut w, \"GET\", &url, &none, \"\")\n    try server.serve_one(&router, 5000)\n    var r = c.reader()\n    let resp = try read_response(&mut r)\n    expect_eq(resp.status, 200)\n    expect_eq(resp.body, \"hello nx\")\n    expect_eq(resp.header(\"content-type\").?, \"text/plain; charset=utf-8\")\n    c.close()\n\n    var c2 = try net.TcpStream.connect_timeout(\"127.0.0.1\", port, 5000)\n    c2.set_timeout(5000)\n    var w2 = c2.writer()\n    url.path = String.from(\"/echo\")\n    try send_request(&mut w2, \"POST\", &url, &none, \"payload bytes\")\n    try server.serve_one(&router, 5000)\n    var r2 = c2.reader()\n    let resp2 = try read_response(&mut r2)\n    expect_eq(resp2.status, 201)\n    expect_eq(resp2.body, \"payload bytes\")\n    c2.close()\n\n    var c3 = try net.TcpStream.connect_timeout(\"127.0.0.1\", port, 5000)\n    c3.set_timeout(5000)\n    try c3.send(\"GET /missing HTTP/1.1\\r\\nHost: x\\r\\n\\r\\n\")\n    try server.serve_one(&router, 5000)\n    var r3 = c3.reader()\n    expect_eq((try read_response(&mut r3)).status, 404)\n    c3.close()\n    server.close()\n}\n\ntest \"chunked bodies\" {\n    // a canned response fed through a file-backed reader\n    let path = fs.temp_path(\"nxhttp-\")\n    try fs.write(path, \"HTTP/1.1 200 OK\\r\\nTransfer-Encoding: chunked\\r\\nX-Test: yes\\r\\n\\r\\n5\\r\\nhello\\r\\n6;ext=1\\r\\n world\\r\\n0\\r\\n\\r\\n\")\n    var r = try stream.Reader.open(path)\n    let resp = try read_response(&mut r)\n    r.close()\n    try fs.remove(path)\n    expect_eq(resp.status, 200)\n    expect_eq(resp.reason, \"OK\")\n    expect_eq(resp.body, \"hello world\")\n    expect_eq(resp.header(\"x-test\").?, \"yes\")\n    expect(resp.ok())\n}\n";
static const char nx_str_1296[5] = "json";
static const char nx_str_1297[16605] = "// std.json: a JSON parser and serializer, written in Nexium.\n//\n// `import std.json` then `json.parse(text)`, `json.stringify(&value)`.\n// Values are the `Json` enum below; arrays and objects own their children.\n// Numbers are f64 (JSON has one number type); integers up to 2^53 round trip.\n\npub struct Member {\n    key: String\n    value: Json\n}\n\npub enum Json {\n    Null,\n    Bool(bool),\n    Num(f64),\n    Str(String),\n    Arr(List(Json)),\n    Obj(List(Member)),\n}\n\n// ---------------------------------------------------------------- building\n\npub fn null_value() -> Json { return Json.Null }\npub fn boolean(b: bool) -> Json { return Json.Bool(b) }\npub fn number(n: f64) -> Json { return Json.Num(n) }\npub fn string(s: []u8) -> Json { return Json.Str(String.from(s)) }\npub fn array() -> Json { return Json.Arr(List(Json).new()) }\npub fn object() -> Json { return Json.Obj(List(Member).new()) }\n\n/// Append to an array; does nothing when `v` is not an array.\npub fn push(v: *mut Json, own item: Json) {\n    match v.*{\n        .Arr(items) => items.append(item),\n        _ => { },\n    }\n}\n\n/// Set a key on an object (replacing an existing one); does nothing otherwise.\npub fn set(v: *mut Json, key: []u8, own value: Json) {\n    match v.*{\n        .Obj(members) => {\n            for m, i in members {\n                if m.key == key {\n                    members[i] = Member{ .key = String.from(key), .value = value }\n                    return\n                }\n            }\n            members.append(Member{ .key = String.from(key), .value = value })\n        },\n        _ => { },\n    }\n}\n\n// ---------------------------------------------------------------- reading\n\n/// The member `key` of an object, or null.\npub fn get(v: *Json, key: []u8) -> ?*Json {\n    match v.*{\n        .Obj(members) => {\n            for m, i in members {\n                if m.key == key { return &members[i].value }\n            }\n            return null\n        },\n        _ => return null,\n    }\n}\n\n/// The member `key` of an object, mutable, or null.\npub fn get_mut(v: *mut Json, key: []u8) -> ?*mut Json{\n    match v.*{\n        .Obj(members) => {\n            for m, i in members {\n                if m.key == key { return &mut members[i].value }\n            }\n            return null\n        },\n        _ => return null,\n    }\n}\n\n/// Element `i` of an array, mutable, or null.\npub fn at_mut(v: *mut Json, i: usize) -> ?*mut Json{\n    match v.*{\n        .Arr(items) => {\n            if i < items.len { return &mut items[i] }\n            return null\n        },\n        _ => return null,\n    }\n}\n\n/// Element `i` of an array, or null.\npub fn at(v: *Json, i: usize) -> ?*Json {\n    match v.*{\n        .Arr(items) => {\n            if i < items.len { return &items[i] }\n            return null\n        },\n        _ => return null,\n    }\n}\n\n/// Number of elements or members; 0 for scalars.\npub fn len(v: *Json) -> usize {\n    match v.*{\n        .Arr(items) => items.len,\n        .Obj(members) => members.len,\n        _ => 0,\n    }\n}\n\npub fn is_null(v: *Json) -> bool {\n    match v.*{\n        .Null => true,\n        _ => false,\n    }\n}\n\npub fn as_bool(v: *Json) -> ?bool {\n    match v.*{\n        .Bool(b) => b,\n        _ => null,\n    }\n}\n\npub fn as_num(v: *Json) -> ?f64 {\n    match v.*{\n        .Num(n) => n,\n        _ => null,\n    }\n}\n\npub fn as_str(v: *Json) -> ?[]u8 {\n    match v.*{\n        .Str(s) => s.as_slice(),\n        _ => null,\n    }\n}\n\n/// Keys of an object in order; empty for anything else.\npub fn keys(v: *Json) -> List([]u8) {\n    var out = List([]u8).new()\n    match v.*{\n        .Obj(members) => { for m in members { out.append(m.key.as_slice()) } },\n        _ => { },\n    }\n    return out\n}\n\n// ---------------------------------------------------------------- parsing\n\nstruct Parser {\n    src: []u8\n    pos: usize\n}\n\nfn is_ws(c: u8) -> bool { return c == ' ' or c == '\\t' or c == '\\n' or c == '\\r' }\n\nimpl Parser {\n    fn peek(self: *Self) -> u8 {\n        return if self.pos < self.src.len { self.src[self.pos] } else { 0 }\n    }\n\n    fn skip_ws(self: *mut Self) {\n        while self.pos < self.src.len and is_ws(self.src[self.pos]) { self.pos += 1 }\n    }\n\n    fn expect_word(self: *mut Self, word: []u8) -> !void {\n        if self.pos + word.len > self.src.len { return error.InvalidInput }\n        if self.src[self.pos..self.pos + word.len] != word { return error.InvalidInput }\n        self.pos += word.len\n    }\n\n    fn hex4(self: *mut Self) -> !u32 {\n        if self.pos + 4 > self.src.len { return error.InvalidInput }\n        var v: u32 = 0\n        for _ in 0..4 {\n            let c = self.src[self.pos]\n            var d: u32 = 0\n            if c >= '0' and c <= '9' { d = (c - '0') as u32 }\n            else if c >= 'a' and c <= 'f' { d = (c - 'a') as u32 + 10 }\n            else if c >= 'A' and c <= 'F' { d = (c - 'A') as u32 + 10 }\n            else { return error.InvalidInput }\n            v = v * 16 + d\n            self.pos += 1\n        }\n        return v\n    }\n\n    fn push_utf8(out: *mut String, cp: u32) {\n        if cp < 0x80 {\n            out.push_byte(cp as u8)\n        } else if cp < 0x800 {\n            out.push_byte((0xC0 | (cp >> 6)) as u8)\n            out.push_byte((0x80 | (cp & 0x3F)) as u8)\n        } else if cp < 0x10000 {\n            out.push_byte((0xE0 | (cp >> 12)) as u8)\n            out.push_byte((0x80 | ((cp >> 6) & 0x3F)) as u8)\n            out.push_byte((0x80 | (cp & 0x3F)) as u8)\n        } else {\n            out.push_byte((0xF0 | (cp >> 18)) as u8)\n            out.push_byte((0x80 | ((cp >> 12) & 0x3F)) as u8)\n            out.push_byte((0x80 | ((cp >> 6) & 0x3F)) as u8)\n            out.push_byte((0x80 | (cp & 0x3F)) as u8)\n        }\n    }\n\n    fn parse_string(self: *mut Self) -> !String {\n        // at the opening quote\n        self.pos += 1\n        var out = String.new()\n        while true {\n            if self.pos >= self.src.len { return error.InvalidInput }\n            let c = self.src[self.pos]\n            self.pos += 1\n            if c == '\"' { break }\n            if c == '\\\\' {\n                if self.pos >= self.src.len { return error.InvalidInput }\n                let e = self.src[self.pos]\n                self.pos += 1\n                if e == '\"' { out.push_byte('\"') }\n                else if e == '\\\\' { out.push_byte('\\\\') }\n                else if e == '/' { out.push_byte('/') }\n                else if e == 'b' { out.push_byte(8) }\n                else if e == 'f' { out.push_byte(12) }\n                else if e == 'n' { out.push_byte('\\n') }\n                else if e == 'r' { out.push_byte('\\r') }\n                else if e == 't' { out.push_byte('\\t') }\n                else if e == 'u' {\n                    var cp = try self.hex4()\n                    if cp >= 0xD800 and cp <= 0xDBFF {\n                        // surrogate pair: \\uD83D\\uDE00\n                        try self.expect_word(\"\\\\u\")\n                        let lo = try self.hex4()\n                        if lo < 0xDC00 or lo > 0xDFFF { return error.InvalidInput }\n                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)\n                    }\n                    Parser.push_utf8(&mut out, cp)\n                } else {\n                    return error.InvalidInput\n                }\n            } else if c < 0x20 {\n                return error.InvalidInput\n            } else {\n                out.push_byte(c)\n            }\n        }\n        return out\n    }\n\n    fn parse_number(self: *mut Self) -> !f64 {\n        let start = self.pos\n        if self.peek() == '-' { self.pos += 1 }\n        if ! (self.peek() >= '0' and self.peek() <= '9') { return error.InvalidInput }\n        while self.peek() >= '0' and self.peek() <= '9' { self.pos += 1 }\n        if self.peek() == '.' {\n            self.pos += 1\n            if ! (self.peek() >= '0' and self.peek() <= '9') { return error.InvalidInput }\n            while self.peek() >= '0' and self.peek() <= '9' { self.pos += 1 }\n        }\n        if self.peek() == 'e' or self.peek() == 'E' {\n            self.pos += 1\n            if self.peek() == '+' or self.peek() == '-' { self.pos += 1 }\n            if ! (self.peek() >= '0' and self.peek() <= '9') { return error.InvalidInput }\n            while self.peek() >= '0' and self.peek() <= '9' { self.pos += 1 }\n        }\n        let n = self.src[start..self.pos].parse_float() catch |e| return error.InvalidInput\n        return n\n    }\n\n    fn parse_value(self: *mut Self, depth: u32) -> !Json {\n        if depth > 256 { return error.InvalidInput }\n        self.skip_ws()\n        let c = self.peek()\n        if c == '{' {\n            self.pos += 1\n            var members = List(Member).new()\n            self.skip_ws()\n            if self.peek() == '}' {\n                self.pos += 1\n                return Json.Obj(members)\n            }\n            while true {\n                self.skip_ws()\n                if self.peek() != '\"' { return error.InvalidInput }\n                let key = try self.parse_string()\n                self.skip_ws()\n                if self.peek() != ':' { return error.InvalidInput }\n                self.pos += 1\n                let value = try self.parse_value(depth + 1)\n                members.append(Member{ .key = key, .value = value })\n                self.skip_ws()\n                let d = self.peek()\n                self.pos += 1\n                if d == '}' { break }\n                if d != ',' { return error.InvalidInput }\n            }\n            return Json.Obj(members)\n        }\n        if c == '[' {\n            self.pos += 1\n            var items = List(Json).new()\n            self.skip_ws()\n            if self.peek() == ']' {\n                self.pos += 1\n                return Json.Arr(items)\n            }\n            while true {\n                let v = try self.parse_value(depth + 1)\n                items.append(v)\n                self.skip_ws()\n                let d = self.peek()\n                self.pos += 1\n                if d == ']' { break }\n                if d != ',' { return error.InvalidInput }\n            }\n            return Json.Arr(items)\n        }\n        if c == '\"' {\n            let s = try self.parse_string()\n            return Json.Str(s)\n        }\n        if c == 't' {\n            try self.expect_word(\"true\")\n            return Json.Bool(true)\n        }\n        if c == 'f' {\n            try self.expect_word(\"false\")\n            return Json.Bool(false)\n        }\n        if c == 'n' {\n            try self.expect_word(\"null\")\n            return Json.Null\n        }\n        if c == '-' or (c >= '0' and c <= '9') {\n            let n = try self.parse_number()\n            return Json.Num(n)\n        }\n        return error.InvalidInput\n    }\n}\n\n/// Parse a JSON document. Trailing whitespace is allowed, anything else is an error.\npub fn parse(text: []u8) -> !Json {\n    var p = Parser{ .src = text, .pos = 0 }\n    let v = try p.parse_value(0)\n    p.skip_ws()\n    if p.pos != text.len { return error.InvalidInput }\n    return v\n}\n\n// ---------------------------------------------------------------- writing\n\nfn write_string(out: *mut String, s: []u8) {\n    out.push_byte('\"')\n    for c in s {\n        if c == '\"' { out.append(\"\\\\\\\"\") }\n        else if c == '\\\\' { out.append(\"\\\\\\\\\") }\n        else if c == '\\n' { out.append(\"\\\\n\") }\n        else if c == '\\r' { out.append(\"\\\\r\") }\n        else if c == '\\t' { out.append(\"\\\\t\") }\n        else if c == 8 { out.append(\"\\\\b\") }\n        else if c == 12 { out.append(\"\\\\f\") }\n        else if c < 0x20 {\n            out.append(\"\\\\u00\")\n            let hex = \"0123456789abcdef\"\n            out.push_byte(hex[(c >> 4) as usize])\n            out.push_byte(hex[(c & 15) as usize])\n        } else {\n            out.push_byte(c)\n        }\n    }\n    out.push_byte('\"')\n}\n\nfn write_number(out: *mut String, n: f64) {\n    // integers print without a fraction; everything else with enough digits to round trip\n    if n == math.floor(n) and math.abs(n) < 9007199254740992.0 {\n        out.append(format(\"{}\", .{n as i64}))\n    } else {\n        out.append(format(\"{}\", .{n}))\n    }\n}\n\nfn write_value(out: *mut String, v: *Json, indent: usize, level: usize) {\n    match v.*{\n        .Null => out.append(\"null\"),\n        .Bool(b) => out.append(if b { \"true\" } else { \"false\" }),\n        .Num(n) => write_number(out, n),\n        .Str(s) => write_string(out, s),\n        .Arr(items) => {\n            if items.len == 0 {\n                out.append(\"[]\")\n                return\n            }\n            out.push_byte('[')\n            for it, i in items {\n                if i > 0 { out.push_byte(',') }\n                newline(out, indent, level + 1)\n                write_value(out, &it, indent, level + 1)\n            }\n            newline(out, indent, level)\n            out.push_byte(']')\n        },\n        .Obj(members) => {\n            if members.len == 0 {\n                out.append(\"{}\")\n                return\n            }\n            out.push_byte('{')\n            for m, i in members {\n                if i > 0 { out.push_byte(',') }\n                newline(out, indent, level + 1)\n                write_string(out, m.key)\n                out.push_byte(':')\n                if indent > 0 { out.push_byte(' ') }\n                write_value(out, &m.value, indent, level + 1)\n            }\n            newline(out, indent, level)\n            out.push_byte('}')\n        },\n    }\n}\n\nfn newline(out: *mut String, indent: usize, level: usize) {\n    if indent == 0 { return }\n    out.push_byte('\\n')\n    for _ in 0..indent * level { out.push_byte(' ') }\n}\n\n/// Compact text: no whitespace.\npub fn stringify(v: *Json) -> String {\n    var out = String.new()\n    write_value(&mut out, v, 0, 0)\n    return out\n}\n\n/// Indented text, `indent` spaces per level.\npub fn pretty(v: *Json, indent: usize) -> String {\n    var out = String.new()\n    write_value(&mut out, v, indent, 0)\n    return out\n}\n\n// ---------------------------------------------------------------- tests\n\ntest \"scalars\" {\n    let t = try parse(\" true \")\n    expect_eq(as_bool(&t) orelse false, true)\n    let n = try parse(\"-12.5e1\")\n    expect_eq(as_num(&n) orelse 0.0, -125.0)\n    let s = try parse(\"\\\"a\\\\\\\"b\\\\n\\\\u0041\\\\u00e9\\\\ud83d\\\\ude00\\\"\")\n    expect_eq(as_str(&s) orelse \"\", \"a\\\"b\\nA\303\251\360\237\230\200\")\n    let z = try parse(\"null\")\n    expect(is_null(&z))\n    expect_eq(stringify(&t), \"true\")\n    expect_eq(stringify(&n), \"-125\")\n    expect_eq(stringify(&s), \"\\\"a\\\\\\\"b\\\\nA\303\251\360\237\230\200\\\"\")\n}\n\ntest \"arrays and objects\" {\n    let doc = try parse(\"{\\\"name\\\": \\\"nexium\\\", \\\"tags\\\": [\\\"lang\\\", 2, false, null], \\\"nested\\\": {\\\"k\\\": [ ]}}\")\n    expect_eq(len(&doc), 3)\n    expect_eq(as_str(get(&doc, \"name\") orelse &doc) orelse \"\", \"nexium\")\n    let tags = get(&doc, \"tags\") orelse &doc\n    expect_eq(len(tags), 4)\n    expect_eq(as_num(at(tags, 1) orelse tags) orelse 0.0, 2.0)\n    expect(get(&doc, \"missing\") == null)\n    expect(at(tags, 9) == null)\n    let ks = keys(&doc)\n    expect_eq(ks.len, 3)\n    expect_eq(ks[2], \"nested\")\n    expect_eq(stringify(&doc), \"{\\\"name\\\":\\\"nexium\\\",\\\"tags\\\":[\\\"lang\\\",2,false,null],\\\"nested\\\":{\\\"k\\\":[]}}\")\n}\n\ntest \"pretty printing\" {\n    let doc = try parse(\"{\\\"a\\\":[1,{\\\"b\\\":true}],\\\"c\\\":{}}\")\n    expect_eq(pretty(&doc, 2), \"{\\n  \\\"a\\\": [\\n    1,\\n    {\\n      \\\"b\\\": true\\n    }\\n  ],\\n  \\\"c\\\": {}\\n}\")\n}\n\ntest \"mutable access\" {\n    var doc = try parse(\"{\\\"a\\\": [1], \\\"b\\\": {}}\")\n    push(get_mut(&mut doc, \"a\") orelse &mut doc, number(2))\n    set(get_mut(&mut doc, \"b\") orelse &mut doc, \"c\", boolean(true))\n    if let first = at_mut(get_mut(&mut doc, \"a\") orelse &mut doc, 0) {\n        first.*= string(\"one\")\n    }\n    expect_eq(stringify(&doc), \"{\\\"a\\\":[\\\"one\\\",2],\\\"b\\\":{\\\"c\\\":true}}\")\n}\n\ntest \"building\" {\n    var root = object()\n    set(&mut root, \"n\", number(3.25))\n    set(&mut root, \"s\", string(\"x\"))\n    var arr = array()\n    push(&mut arr, boolean(true))\n    push(&mut arr, null_value())\n    set(&mut root, \"arr\", arr)\n    set(&mut root, \"n\", number(4))\n    expect_eq(stringify(&root), \"{\\\"n\\\":4,\\\"s\\\":\\\"x\\\",\\\"arr\\\":[true,null]}\")\n}\n\nfn fails(text: []u8) -> bool {\n    let r = parse(text) catch |e| return true\n    _ = r\n    return false\n}\n\ntest \"errors\" {\n    expect(fails(\"\"))\n    expect(fails(\"{\"))\n    expect(fails(\"[1,]\"))\n    expect(fails(\"{\\\"a\\\" 1}\"))\n    expect(fails(\"tru\"))\n    expect(fails(\"01x\"))\n    expect(fails(\"\\\"unterminated\"))\n    expect(fails(\"\\\"bad \\\\q escape\\\"\"))\n    expect(fails(\"1 2\"))\n    expect(!fails(\" [ ] \"))\n}\n\ntest \"round trip\" {\n    let text = \"[0,1.5,-2,1e21,\\\"\\\\u0001\\\",{\\\"k\\\":[[],{}]}]\"\n    let v = try parse(text)\n    let again = try parse(stringify(&v))\n    expect_eq(stringify(&again), stringify(&v))\n}\n";
static const char nx_str_1298[6] = "lists";
static const char nx_str_1299[6507] = "// std.lists: generic helpers over slices and Lists, written in Nexium.\n//\n// `import std.lists` then `lists.sum(xs)`, `lists.map(f, xs)`, ...\n// Functions take slices, so arrays, Lists, and slices all work; results that\n// are new collections are returned as owned `List`s.\n\n/// Sum of the elements.\npub fn sum(comptime T: type, xs: []T) -> T {\n    var total: T = 0\n    for x in xs { total += x }\n    return total\n}\n\n/// Smallest element, or null when empty.\npub fn min(comptime T: type where T: Ord, xs: []T) -> ?T {\n    if xs.len == 0 { return null }\n    var best = xs[0]\n    for x in xs { if x < best { best = x } }\n    return best\n}\n\n/// Largest element, or null when empty.\npub fn max(comptime T: type where T: Ord, xs: []T) -> ?T {\n    if xs.len == 0 { return null }\n    var best = xs[0]\n    for x in xs { if x > best { best = x } }\n    return best\n}\n\n/// Position of the largest element, or null when empty.\npub fn arg_max(comptime T: type where T: Ord, xs: []T) -> ?usize {\n    if xs.len == 0 { return null }\n    var at: usize = 0\n    for x, i in xs { if x > xs[at] { at = i } }\n    return at\n}\n\n/// True when every element satisfies `pred`.\npub fn all(comptime T: type, xs: []T, pred: fn(T) -> bool) -> bool {\n    for x in xs { if !pred(x) { return false } }\n    return true\n}\n\n/// True when some element satisfies `pred`.\npub fn any(comptime T: type, xs: []T, pred: fn(T) -> bool) -> bool {\n    for x in xs { if pred(x) { return true } }\n    return false\n}\n\n/// How many elements satisfy `pred`.\npub fn count_if(comptime T: type, xs: []T, pred: fn(T) -> bool) -> usize {\n    var n: usize = 0\n    for x in xs { if pred(x) { n += 1 } }\n    return n\n}\n\n/// The elements that satisfy `pred`, in order.\npub fn filter(comptime T: type, xs: []T, pred: fn(T) -> bool) -> List(T) {\n    var out = List(T).new()\n    for x in xs { if pred(x) { out.append(x) } }\n    return out\n}\n\n/// `f` applied to every element.\npub fn map(comptime T: type, comptime U: type, xs: []T, f: fn(T) -> U) -> List(U) {\n    var out = List(U).with_capacity(xs.len)\n    for x in xs { out.append(f(x)) }\n    return out\n}\n\n/// Left fold: `f(f(f(init, x0), x1), x2)`.\npub fn fold(comptime T: type, comptime A: type, xs: []T, init: A, f: fn(A, T) -> A) -> A {\n    var acc = init\n    for x in xs { acc = f(acc, x) }\n    return acc\n}\n\n/// First element satisfying `pred`, or null.\npub fn find(comptime T: type, xs: []T, pred: fn(T) -> bool) -> ?T {\n    for x in xs { if pred(x) { return x } }\n    return null\n}\n\n/// Position of the first element satisfying `pred`, or null.\npub fn position(comptime T: type, xs: []T, pred: fn(T) -> bool) -> ?usize {\n    for x, i in xs { if pred(x) { return i } }\n    return null\n}\n\n/// A reversed copy.\npub fn reversed(comptime T: type, xs: []T) -> List(T) {\n    var out = List(T).with_capacity(xs.len)\n    var i = xs.len\n    while i > 0 {\n        i -= 1\n        out.append(xs[i])\n    }\n    return out\n}\n\n/// Adjacent duplicates removed (sort first for global dedup).\npub fn dedup(comptime T: type where T: Eq, xs: []T) -> List(T) {\n    var out = List(T).new()\n    for x, i in xs {\n        if i == 0 or x != xs[i - 1] { out.append(x) }\n    }\n    return out\n}\n\n/// The first `n` elements (or all when shorter).\npub fn take(comptime T: type, xs: []T, n: usize) -> []T{\n    return if n < xs.len { xs[0..n] } else { xs }\n}\n\n/// Everything after the first `n` elements.\npub fn drop(comptime T: type, xs: []T, n: usize) -> []T{\n    return if n < xs.len { xs[n..] } else { xs[xs.len..] }\n}\n\n/// Consecutive windows of `size`, as start indices; `for i in windows(xs, 3)` then `xs[i..i+3]`.\npub fn window_starts(len: usize, size: usize) -> List(usize) {\n    var out = List(usize).new()\n    if size == 0 or size > len { return out }\n    for i in 0..len - size + 1 { out.append(i) }\n    return out\n}\n\n/// Pairs (a[i], b[i]) up to the shorter length.\npub fn zip(comptime A: type, comptime B: type, a: []A, b: []B) -> List((A, B)) {\n    let n = if a.len < b.len { a.len } else { b.len }\n    var out = List((A, B)).with_capacity(n)\n    for i in 0..n { out.append((a[i], b[i])) }\n    return out\n}\n\n/// Elements repeated `times` times in sequence.\npub fn repeat(comptime T: type, xs: []T, times: usize) -> List(T) {\n    var out = List(T).with_capacity(xs.len * times)\n    for _ in 0..times { for x in xs { out.append(x) } }\n    return out\n}\n\n/// True when `xs` starts with `prefix`.\npub fn starts_with(comptime T: type where T: Eq, xs: []T, prefix: []T) -> bool {\n    if prefix.len > xs.len { return false }\n    for p, i in prefix { if xs[i] != p { return false } }\n    return true\n}\n\nfn is_even(x: i32) -> bool { return x % 2 == 0 }\nfn double(x: i32) -> i32 { return x * 2 }\nfn to_len(s: []u8) -> usize { return s.len }\nfn add(a: i64, b: i32) -> i64 { return a + b as i64 }\n\ntest \"sum min max\" {\n    let xs = [3, 1, 4, 1, 5]\n    expect_eq(sum(i32, xs[..]), 14)\n    expect_eq(min(i32, xs[..]) orelse -1, 1)\n    expect_eq(max(i32, xs[..]) orelse -1, 5)\n    expect_eq(arg_max(i32, xs[..]) orelse 99, 4)\n    let none: [0]i32 = []\n    expect(max(i32, none[..]) == null)\n    let fs = [1.5, 2.5]\n    expect_eq(sum(f64, fs[..]), 4.0)\n}\n\ntest \"predicates\" {\n    let xs = [2, 4, 6]\n    expect(all(i32, xs[..], is_even))\n    let ys = [2, 3]\n    expect(!all(i32, ys[..], is_even))\n    expect(any(i32, ys[..], is_even))\n    expect_eq(count_if(i32, ys[..], is_even), 1)\n    expect_eq(find(i32, ys[..], is_even) orelse 0, 2)\n    expect_eq(position(i32, ys[..], is_even) orelse 99, 0)\n}\n\ntest \"map filter fold\" {\n    let xs = [1, 2, 3, 4]\n    let evens = filter(i32, xs[..], is_even)\n    expect_eq(evens.len, 2)\n    expect_eq(evens[1], 4)\n    let doubled = map(i32, i32, xs[..], double)\n    expect_eq(doubled[3], 8)\n    let words = [\"a\", \"bbb\"]\n    let lens = map([]u8, usize, words[..], to_len)\n    expect_eq(lens[1], 3)\n    expect_eq(fold(i32, i64, xs[..], 100, add), 110)\n}\n\ntest \"shapes\" {\n    let xs = [1, 1, 2, 2, 2, 3]\n    let d = dedup(i32, xs[..])\n    expect_eq(d.len, 3)\n    let r = reversed(i32, xs[..])\n    expect_eq(r[0], 3)\n    expect_eq(take(i32, xs[..], 2).len, 2)\n    expect_eq(take(i32, xs[..], 20).len, 6)\n    expect_eq(drop(i32, xs[..], 4).len, 2)\n    expect_eq(drop(i32, xs[..], 20).len, 0)\n    expect_eq(window_starts(5, 3).len, 3)\n    let names = [\"x\", \"y\"]\n    let pairs = zip([]u8, i32, names[..], xs[..])\n    expect_eq(pairs.len, 2)\n    expect_eq(pairs[1].0, \"y\")\n    expect_eq(repeat(i32, xs[0..2], 3).len, 6)\n    expect(starts_with(i32, xs[..], xs[0..3]))\n    expect(!starts_with(i32, xs[0..2], xs[..]))\n}\n";
static const char nx_str_1300[8783] = "// std.net: TCP and UDP with addresses, written in Nexium over the `net.*`\n// primitives.\n//\n// `import std.net` then:\n//\n//     var c = try net.TcpStream.connect(\"example.com\", 80)\n//     try c.send(\"GET / HTTP/1.0\\r\\nHost: example.com\\r\\n\\r\\n\")\n//     let reply = try c.recv_all()                 // until the peer closes\n//     c.close()\n//\n//     var l = try net.TcpListener.bind(\"127.0.0.1\", 8080)\n//     while true {\n//         var conn = try l.accept()\n//         var r = conn.reader()                     // a std.stream Reader\n//         let line = try r.read_line()\n//         try conn.send(\"ok\\n\")\n//         conn.close()\n//     }\n//\n//     var u = try net.UdpSocket.bind(\"0.0.0.0\", 0)\n//     try u.send_to(\"127.0.0.1\", 9000, \"ping\")\n//     let d = try u.recv_from(1500)                 // d.data, d.from\n//\n// Every call blocks; timeouts are per socket (`set_timeout`, milliseconds,\n// 0 waits forever) and expire with `error.Timeout`. `recv` returns an empty\n// String when the peer has closed. Errors: `NotFound` (name lookup),\n// `ConnectionRefused`, `Timeout`, `IoError`.\n\nimport std.stream\n\n/// A host and a port.\npub struct Addr {\n    host: String\n    port: u16\n}\n\n/// Split `host:port` or `[v6]:port`; null when there is no valid port.\npub fn parse_addr(s: []u8) -> ?Addr {\n    var i = s.len\n    while i > 0 and s[i - 1] != ':' { i -= 1 }\n    if i == 0 or i == s.len { return null }\n    let port = s[i..s.len].parse_int(u16) catch return null\n    var host = s[0..i - 1]\n    if host.len >= 2 and host[0] == '[' and host[host.len - 1] == ']' { host = host[1..host.len - 1] }\n    return Addr{ .host = String.from(host), .port = port }\n}\n\n/// The port at the end of `host:port`, or null.\npub fn port_of(s: []u8) -> ?u16 {\n    let a = parse_addr(s) orelse return null\n    return a.port\n}\n\n/// The addresses a name resolves to, numeric, in resolver order.\npub fn resolve(host: []u8) -> !List(String) {\n    return net.resolve(host)\n}\n\n// ------------------------------------------------------------------ TCP\n\n/// A connected TCP socket.\npub struct TcpStream {\n    sock: i64\n    timeout_ms: i64\n    open: bool\n}\n\nimpl TcpStream {\n    /// Connect with a 10 second timeout.\n    pub fn connect(host: []u8, port: u16) -> !TcpStream {\n        return TcpStream.connect_timeout(host, port, 10000)\n    }\n\n    /// Connect; `timeout_ms` 0 waits as long as the OS does.\n    pub fn connect_timeout(host: []u8, port: u16, timeout_ms: i64) -> !TcpStream {\n        let s = try net.connect(host, port, timeout_ms)\n        return TcpStream{ .sock = s, .timeout_ms = timeout_ms, .open = true }\n    }\n\n    /// Wrap a socket from `net.accept` or `net.connect`.\n    pub fn from_socket(sock: i64) -> TcpStream {\n        return TcpStream{ .sock = sock, .timeout_ms = 0, .open = true }\n    }\n\n    /// The receive timeout in milliseconds; 0 waits forever.\n    pub fn set_timeout(self: *mut Self, ms: i64) {\n        self.timeout_ms = ms\n    }\n\n    pub fn send(self: *Self, data: []u8) -> !void {\n        return net.send(self.sock, data)\n    }\n\n    /// Up to `n` bytes; empty when the peer has closed.\n    pub fn recv(self: *Self, n: usize) -> !String {\n        return net.recv(self.sock, n, self.timeout_ms)\n    }\n\n    /// Everything until the peer closes.\n    pub fn recv_all(self: *Self) -> !String {\n        var out = String.new()\n        while true {\n            let chunk = try self.recv(65536)\n            if chunk.len == 0 { break }\n            out.append(chunk)\n        }\n        return out\n    }\n\n    /// The remote address as `ip:port`.\n    pub fn peer(self: *Self) -> !String {\n        return net.peer(self.sock)\n    }\n\n    /// The local address as `ip:port`.\n    pub fn local(self: *Self) -> !String {\n        return net.local(self.sock)\n    }\n\n    /// A buffered reader over the socket (lines, chunks); does not own it.\n    pub fn reader(self: *Self) -> stream.Reader {\n        return stream.Reader.from_socket(self.sock)\n    }\n\n    /// A buffered writer over the socket; flush it before waiting for a reply.\n    pub fn writer(self: *Self) -> stream.Writer {\n        return stream.Writer.from_socket(self.sock)\n    }\n\n    pub fn close(self: *mut Self) {\n        if self.open {\n            net.close(self.sock) catch { }\n            self.open = false\n        }\n    }\n}\n\n/// A listening TCP socket.\npub struct TcpListener {\n    sock: i64\n    open: bool\n}\n\nimpl TcpListener {\n    /// Bind and listen; port 0 picks a free port (see `local`).\n    pub fn bind(host: []u8, port: u16) -> !TcpListener {\n        let s = try net.listen(host, port)\n        return TcpListener{ .sock = s, .open = true }\n    }\n\n    /// The bound address as `ip:port`.\n    pub fn local(self: *Self) -> !String {\n        return net.local(self.sock)\n    }\n\n    /// The bound port.\n    pub fn port(self: *Self) -> !u16 {\n        let a = try net.local(self.sock)\n        return port_of(a) orelse return error.IoError\n    }\n\n    /// Wait for a connection.\n    pub fn accept(self: *Self) -> !TcpStream {\n        return self.accept_timeout(0)\n    }\n\n    /// Wait up to `timeout_ms` for a connection (`error.Timeout` otherwise).\n    pub fn accept_timeout(self: *Self, timeout_ms: i64) -> !TcpStream {\n        let s = try net.accept(self.sock, timeout_ms)\n        return TcpStream{ .sock = s, .timeout_ms = 0, .open = true }\n    }\n\n    pub fn close(self: *mut Self) {\n        if self.open {\n            net.close(self.sock) catch { }\n            self.open = false\n        }\n    }\n}\n\n// ------------------------------------------------------------------ UDP\n\n/// A received datagram and who sent it (`ip:port`).\npub struct Datagram {\n    data: String\n    from: String\n}\n\n/// A bound UDP socket.\npub struct UdpSocket {\n    sock: i64\n    timeout_ms: i64\n    open: bool\n}\n\nimpl UdpSocket {\n    /// Bind; port 0 picks a free port.\n    pub fn bind(host: []u8, port: u16) -> !UdpSocket {\n        let s = try net.udp_bind(host, port)\n        return UdpSocket{ .sock = s, .timeout_ms = 0, .open = true }\n    }\n\n    pub fn set_timeout(self: *mut Self, ms: i64) {\n        self.timeout_ms = ms\n    }\n\n    pub fn local(self: *Self) -> !String {\n        return net.local(self.sock)\n    }\n\n    pub fn port(self: *Self) -> !u16 {\n        let a = try net.local(self.sock)\n        return port_of(a) orelse return error.IoError\n    }\n\n    pub fn send_to(self: *Self, host: []u8, port: u16, data: []u8) -> !void {\n        return net.send_to(self.sock, host, port, data)\n    }\n\n    /// One datagram of at most `n` bytes.\n    pub fn recv_from(self: *Self, n: usize) -> !Datagram {\n        let data = try net.recv_from(self.sock, n, self.timeout_ms)\n        return Datagram{ .data = data, .from = net.last_peer() }\n    }\n\n    pub fn close(self: *mut Self) {\n        if self.open {\n            net.close(self.sock) catch { }\n            self.open = false\n        }\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"addresses\" {\n    let a = parse_addr(\"example.com:8080\").?\n    expect_eq(a.host, \"example.com\")\n    expect_eq(a.port, 8080)\n    let v6 = parse_addr(\"[::1]:443\").?\n    expect_eq(v6.host, \"::1\")\n    expect_eq(v6.port, 443)\n    expect(parse_addr(\"nope\") == null)\n    expect(parse_addr(\"host:\") == null)\n    expect(parse_addr(\"host:99999\") == null)\n    expect_eq(port_of(\"127.0.0.1:5\").?, 5)\n}\n\ntest \"tcp over loopback\" {\n    var l = try TcpListener.bind(\"127.0.0.1\", 0)\n    let port = try l.port()\n    expect(port > 0)\n    var c = try TcpStream.connect_timeout(\"127.0.0.1\", port, 5000)\n    var s = try l.accept_timeout(5000)\n    s.set_timeout(5000)\n    c.set_timeout(5000)\n    try c.send(\"hello\\nworld\\n\")\n    var r = s.reader()\n    expect_eq((try r.read_line()).?, \"hello\")\n    expect_eq((try r.read_line()).?, \"world\")\n    var w = s.writer()\n    try w.write(\"pong\")\n    try w.flush()\n    expect_eq(try c.recv(64), \"pong\")\n    expect((try c.peer()).len > 0)\n    c.close()\n    expect_eq(try s.recv(64), \"\")\n    s.close()\n    var timed_out = false\n    _ = l.accept_timeout(100) catch |e| {\n        timed_out = e == error.Timeout\n        TcpStream.from_socket(-1)\n    }\n    expect(timed_out)\n    l.close()\n}\n\ntest \"udp to self\" {\n    var u = try UdpSocket.bind(\"127.0.0.1\", 0)\n    u.set_timeout(5000)\n    let port = try u.port()\n    try u.send_to(\"127.0.0.1\", port, \"datagram\")\n    let d = try u.recv_from(64)\n    expect_eq(d.data, \"datagram\")\n    expect(port_of(d.from).?== port)\n    u.close()\n}\n\ntest \"refused and unknown\" {\n    var refused = false\n    _ = TcpStream.connect_timeout(\"127.0.0.1\", 1, 8000) catch |e| {\n        refused = e == error.ConnectionRefused\n        TcpStream.from_socket(-1)\n    }\n    expect(refused)\n    var unknown = false\n    _ = resolve(\"no-such-host.invalid\") catch |e| {\n        unknown = e == error.NotFound\n        List(String).new()\n    }\n    expect(unknown)\n}\n";
static const char nx_str_1301[4] = "num";
static const char nx_str_1302[6187] = "// std.num: integer utilities, written in Nexium.\n//\n// `import std.num` then `num.gcd(12, 18)`, `num.clamp(x, 0, 10)`, ...\n// The `math` namespace (sqrt, sin, pow on floats, ...) is a compiler builtin;\n// this module covers what is naturally integer work.\n\n/// Greatest common divisor (Euclid); gcd(0, 0) is 0.\npub fn gcd(a: u64, b: u64) -> u64 {\n    var x = a\n    var y = b\n    while y != 0 {\n        let t = x % y\n        x = y\n        y = t\n    }\n    return x\n}\n\n/// Least common multiple; lcm(0, n) is 0.\npub fn lcm(a: u64, b: u64) -> u64 {\n    if a == 0 or b == 0 { return 0 }\n    return a / gcd(a, b) * b\n}\n\n/// `x` limited to `lo..=hi`.\npub fn clamp(x: i64, lo: i64, hi: i64) -> i64 {\n    if x < lo { return lo }\n    if x > hi { return hi }\n    return x\n}\n\n/// |a - b| without overflow on the way.\npub fn abs_diff(a: i64, b: i64) -> u64 {\n    return if a > b { (a - b) as u64 } else { (b - a) as u64 }\n}\n\n/// `base` to the `exp`, by squaring; null on overflow.\npub fn pow(base: u64, exp: u32) -> ?u64 {\n    var result: u64 = 1\n    var b = base\n    var e = exp\n    while e > 0 {\n        if e & 1 == 1 {\n            result = result.checked_mul(b) orelse return null\n        }\n        e >>= 1\n        if e > 0 {\n            b = b.checked_mul(b) orelse return null\n        }\n    }\n    return result\n}\n\n/// Integer square root: the largest `r` with `r * r <= n`.\npub fn isqrt(n: u64) -> u64 {\n    if n < 2 { return n }\n    var lo: u64 = 1\n    var hi: u64 = 4294967295\n    while lo < hi {\n        let mid = lo + (hi - lo + 1) / 2\n        if mid <= n / mid { lo = mid }\n        else { hi = mid - 1 }\n    }\n    return lo\n}\n\n/// Trial division; fine for the sizes people type by hand.\npub fn is_prime(n: u64) -> bool {\n    if n < 2 { return false }\n    if n % 2 == 0 { return n == 2 }\n    var d: u64 = 3\n    while d <= isqrt(n) {\n        if n % d == 0 { return false }\n        d += 2\n    }\n    return true\n}\n\n/// The prime factors of `n` with multiplicity, ascending.\npub fn factors(n: u64) -> List(u64) {\n    var out = List(u64).new()\n    var m = n\n    var d: u64 = 2\n    while d * d <= m {\n        while m % d == 0 {\n            out.append(d)\n            m /= d\n        }\n        d += 1\n    }\n    if m > 1 { out.append(m) }\n    return out\n}\n\n/// Decimal digits of `n`, most significant first.\npub fn digits(n: u64) -> List(u8) {\n    var out = List(u8).new()\n    if n == 0 {\n        out.append(0)\n        return out\n    }\n    var m = n\n    while m > 0 {\n        out.append((m % 10) as u8)\n        m /= 10\n    }\n    var i: usize = 0\n    var j = out.len - 1\n    while i < j {\n        let t = out[i]\n        out[i] = out[j]\n        out[j] = t\n        i += 1\n        j -= 1\n    }\n    return out\n}\n\n/// Sum of the decimal digits.\npub fn digit_sum(n: u64) -> u64 {\n    var s: u64 = 0\n    var m = n\n    while m > 0 {\n        s += m % 10\n        m /= 10\n    }\n    return s\n}\n\n/// `n` in base 2..36, upper-case digits.\npub fn to_base(n: u64, base: u64) -> String {\n    let symbols = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n    if n == 0 { return String.from(\"0\") }\n    var tmp = List(u8).new()\n    var m = n\n    while m > 0 {\n        tmp.append(symbols[(m % base) as usize])\n        m /= base\n    }\n    var out = String.with_capacity(tmp.len)\n    var i = tmp.len\n    while i > 0 {\n        i -= 1\n        out.push_byte(tmp[i])\n    }\n    return out\n}\n\n/// Parse in base 2..36 (either case); null on an invalid digit or overflow.\npub fn from_base(text: []u8, base: u64) -> ?u64 {\n    if text.len == 0 { return null }\n    var v: u64 = 0\n    for c in text {\n        var d: u64 = 0\n        if c >= '0' and c <= '9' { d = (c - '0') as u64 }\n        else if c >= 'a' and c <= 'z' { d = (c - 'a') as u64 + 10 }\n        else if c >= 'A' and c <= 'Z' { d = (c - 'A') as u64 + 10 }\n        else { return null }\n        if d >= base { return null }\n        v = v.checked_mul(base) orelse return null\n        v = v.checked_add(d) orelse return null\n    }\n    return v\n}\n\n/// Round up to a multiple of `m` (m > 0).\npub fn round_up(n: u64, m: u64) -> u64 {\n    return (n + m - 1) / m * m\n}\n\n/// True for 1, 2, 4, 8, ...\npub fn is_power_of_two(n: u64) -> bool {\n    return n != 0 and (n & (n - 1)) == 0\n}\n\n/// The smallest power of two >= n (n <= 2^63).\npub fn next_power_of_two(n: u64) -> u64 {\n    var p: u64 = 1\n    while p < n { p <<= 1 }\n    return p\n}\n\n/// Number of set bits.\npub fn popcount(n: u64) -> u32 {\n    var c: u32 = 0\n    var m = n\n    while m != 0 {\n        m &= m - 1\n        c += 1\n    }\n    return c\n}\n\ntest \"gcd lcm\" {\n    expect_eq(gcd(12, 18), 6)\n    expect_eq(gcd(0, 5), 5)\n    expect_eq(gcd(0, 0), 0)\n    expect_eq(lcm(4, 6), 12)\n    expect_eq(lcm(0, 6), 0)\n}\n\ntest \"clamp abs_diff pow\" {\n    expect_eq(clamp(15, 0, 10), 10)\n    expect_eq(clamp(-3, 0, 10), 0)\n    expect_eq(clamp(5, 0, 10), 5)\n    expect_eq(abs_diff(3, 10), 7)\n    expect_eq(abs_diff(10, 3), 7)\n    expect_eq(pow(2, 10) orelse 0, 1024)\n    expect_eq(pow(7, 0) orelse 0, 1)\n    expect(pow(2, 64) == null)\n    expect_eq(pow(3, 5) orelse 0, 243)\n}\n\ntest \"primes and roots\" {\n    expect_eq(isqrt(0), 0)\n    expect_eq(isqrt(15), 3)\n    expect_eq(isqrt(16), 4)\n    expect_eq(isqrt(1000000), 1000)\n    expect(is_prime(2))\n    expect(is_prime(97))\n    expect(!is_prime(1))\n    expect(!is_prime(91))\n    let f = factors(360)\n    expect_eq(f.len, 6)\n    expect_eq(f[0], 2)\n    expect_eq(f[5], 5)\n    expect_eq(factors(97).len, 1)\n}\n\ntest \"digits and bases\" {\n    let d = digits(1230)\n    expect_eq(d.len, 4)\n    expect_eq(d[0], 1)\n    expect_eq(d[3], 0)\n    expect_eq(digits(0).len, 1)\n    expect_eq(digit_sum(1230), 6)\n    expect_eq(to_base(255, 16), \"FF\")\n    expect_eq(to_base(5, 2), \"101\")\n    expect_eq(to_base(0, 7), \"0\")\n    expect_eq(from_base(\"ff\", 16) orelse 0, 255)\n    expect_eq(from_base(\"101\", 2) orelse 0, 5)\n    expect(from_base(\"12\", 2) == null)\n    expect(from_base(\"\", 10) == null)\n}\n\ntest \"bits\" {\n    expect_eq(round_up(13, 8), 16)\n    expect_eq(round_up(16, 8), 16)\n    expect(is_power_of_two(64))\n    expect(!is_power_of_two(0))\n    expect(!is_power_of_two(6))\n    expect_eq(next_power_of_two(100), 128)\n    expect_eq(next_power_of_two(1), 1)\n    expect_eq(popcount(255), 8)\n    expect_eq(popcount(0), 0)\n}\n";
static const char nx_str_1303[3014] = "// std.process: run programs and capture what they print, written in Nexium\n// over the `process.*` primitives.\n//\n// `import std.process` then:\n//\n//     let out = try process.run([\"git\", \"status\", \"--short\"])\n//     if out.ok() { print(\"{}\", .{out.stdout}) }\n//\n//     let r = try process.run_with([\"sort\"], process.Options{ .stdin = \"b\\na\\n\", .cwd = \"\" })\n//     let sh = try process.shell(\"echo hi\")          // cmd /C on Windows, sh -c elsewhere\n//\n// The child inherits the environment. `error.IoError` when the program\n// cannot be started; a non-zero exit is reported in `code`, not as an\n// error. Output is read after stdin is fully written, so a program that\n// produces more than a megabyte of output before reading its input can\n// stall; feed such programs through files.\n\n/// What a finished program left behind.\npub struct Output {\n    code: i32\n    stdout: String\n    stderr: String\n}\n\nimpl Output {\n    pub fn ok(self: *Self) -> bool {\n        return self.code == 0\n    }\n\n    /// stdout without a trailing newline.\n    pub fn text(self: *Self) -> []u8 {\n        return self.stdout.trim()\n    }\n}\n\n/// How to run: text for stdin and a working directory (empty = inherit).\npub struct Options {\n    stdin: []u8\n    cwd: []u8\n}\n\npub fn run_with(argv: [][]u8, opts: Options) -> !Output {\n    let code = try process.exec(argv, opts.stdin, opts.cwd)\n    return Output{ .code = code, .stdout = process.last_stdout(), .stderr = process.last_stderr() }\n}\n\n/// Run and capture, inheriting the working directory, with no stdin.\npub fn run(argv: [][]u8) -> !Output {\n    return run_with(argv, Options{ .stdin = \"\", .cwd = \"\" })\n}\n\n/// Run a command line through the platform shell.\npub fn shell(command: []u8) -> !Output {\n    if os.env(\"COMSPEC\") != null and os.env(\"WINDIR\") != null {\n        let argv = [\"cmd\", \"/C\", command]\n        return run(argv[..])\n    }\n    let argv = [\"sh\", \"-c\", command]\n    return run(argv[..])\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"capture, stdin and a missing program\" {\n    let echoed = try shell(\"echo hello\")\n    expect(echoed.ok())\n    expect_eq(echoed.text(), \"hello\")\n\n    // `sort` exists on every platform; Windows ends lines with CRLF\n    let sort_cmd = [\"sort\"]\n    let sorted = try run_with(sort_cmd[..], Options{ .stdin = \"pear\\napple\\n\", .cwd = \"\" })\n    expect(sorted.ok())\n    let lines = sorted.stdout.lines()\n    expect(lines.len >= 2)\n    expect(lines[0].starts_with(\"apple\"))\n    expect(lines[1].starts_with(\"pear\"))\n\n    // a program that cannot start: an error on Windows, exit 127 from the fork on POSIX\n    let nope = [\"definitely-not-a-program-nx\"]\n    let missing = run(nope[..]) catch |e| {\n        expect(e == error.IoError)\n        Output{ .code = 127, .stdout = String.new(), .stderr = String.new() }\n    }\n    expect_eq(missing.code, 127)\n\n    // a working directory that exists\n    let there = try run_with(sort_cmd[..], Options{ .stdin = \"x\\n\", .cwd = io.temp_dir() })\n    expect(there.ok())\n}\n";
static const char nx_str_1304[6] = "regex";
static const char nx_str_1305[23919] = "// std.regex: regular expressions without backtracking, written in Nexium.\n//\n// `import std.regex` then:\n//\n//     let re = try regex.compile(\"(\\\\w+)@(\\\\w+)\\\\.com\")\n//     if re.is_match(text) { ... }\n//     if let m = re.find(text) { println(\"{} at {}\", .{m.text(), m.start}) }\n//     for m in re.find_all(text) { println(\"{}\", .{m.group(1).?}) }\n//     let out = re.replace_all(text, \"$2:$1\")\n//     let parts = try regex.compile(\",\\\\s*\")\n//     for p in parts.split(\"a, b,c\") { ... }\n//\n// Syntax: literals, `.` (any byte but newline), classes `[a-z]` `[^...]`,\n// `\\d \\w \\s \\D \\W \\S \\b \\B`, escapes `\\. \\\\ \\n \\t \\r`, anchors `^ $`,\n// groups `(...)` and `(?:...)`, alternation `|`, repeats `* + ? {n} {n,}\n// {n,m}` and their lazy forms `*? +? ??`. Matching is a Pike VM (Thompson's\n// NFA simulation), so every search is linear in the text and the pattern;\n// there are no back-references. Patterns and text are bytes.\n\nconst OP_CHAR: u8 = 1\nconst OP_ANY: u8 = 2\nconst OP_CLASS: u8 = 3\nconst OP_SPLIT: u8 = 4\nconst OP_JMP: u8 = 5\nconst OP_SAVE: u8 = 6\nconst OP_MATCH: u8 = 7\nconst OP_START: u8 = 8\nconst OP_END: u8 = 9\nconst OP_WORDB: u8 = 10\nconst OP_NOTWORDB: u8 = 11\n\nstruct Inst {\n    op: u8\n    a: usize\n    b: usize\n}\n\n/// A byte class: inclusive ranges, flat `lo, hi, lo, hi, ...`.\nstruct Class {\n    negate: bool\n    ranges: List(u8)\n}\n\n// ------------------------------------------------------------------ syntax tree\n\nenum Node {\n    Empty,\n    Lit(u8),\n    Any,\n    Cls(usize),\n    Start,\n    End,\n    WordB,\n    NotWordB,\n    Cat(List(Node)),\n    Alt(List(Node)),\n    // node, min, max (-1 = unbounded), greedy\n    Repeat(List(Node), usize, i64, bool),\n    // node, capture index (-1 = non-capturing)\n    Group(List(Node), i64),\n}\n\nstruct Parser {\n    src: []u8\n    pos: usize\n    classes: *mut List(Class)\n    ngroups: usize\n}\n\nfn single(own n: Node) -> List(Node) {\n    var l = List(Node).new()\n    l.append(n)\n    return l\n}\n\nimpl Parser {\n    fn peek(self: *Self) -> u8 {\n        return if self.pos < self.src.len { self.src[self.pos] } else { 0 }\n    }\n\n    fn eof(self: *Self) -> bool {\n        return self.pos >= self.src.len\n    }\n\n    fn parse_alt(self: *mut Self) -> !Node {\n        var branches = List(Node).new()\n        branches.append(try self.parse_cat())\n        while !self.eof() and self.peek() == '|' {\n            self.pos += 1\n            branches.append(try self.parse_cat())\n        }\n        if branches.len == 1 { return branches.pop().?}\n        return Node.Alt(branches)\n    }\n\n    fn parse_cat(self: *mut Self) -> !Node {\n        var items = List(Node).new()\n        while !self.eof() and self.peek() != '|' and self.peek() != ')' {\n            items.append(try self.parse_repeat())\n        }\n        if items.len == 0 { return Node.Empty }\n        if items.len == 1 { return items.pop().?}\n        return Node.Cat(items)\n    }\n\n    fn parse_repeat(self: *mut Self) -> !Node {\n        var atom = try self.parse_atom()\n        while !self.eof() {\n            let c = self.peek()\n            var min: usize = 0\n            var max: i64 = -1\n            if c == '*' {\n                self.pos += 1\n            } else if c == '+' {\n                min = 1\n                self.pos += 1\n            } else if c == '?' {\n                max = 1\n                self.pos += 1\n            } else if c == '{' {\n                let save = self.pos\n                self.pos += 1\n                let lo = self.parse_number()\n                if lo == null {\n                    // a literal brace\n                    self.pos = save\n                    break\n                }\n                min = lo.?\n                max = min as i64\n                if self.peek() == ',' {\n                    self.pos += 1\n                    let hi = self.parse_number()\n                    max = if hi == null { -1 } else { hi.?as i64 }\n                }\n                if self.peek() != '}' { return error.InvalidInput }\n                self.pos += 1\n                if max >= 0 and (max as usize) < min { return error.InvalidInput }\n            } else {\n                break\n            }\n            var greedy = true\n            if !self.eof() and self.peek() == '?' {\n                greedy = false\n                self.pos += 1\n            }\n            atom = Node.Repeat(single(atom), min, max, greedy)\n        }\n        return atom\n    }\n\n    fn parse_number(self: *mut Self) -> ?usize {\n        var n: usize = 0\n        var any = false\n        while !self.eof() and self.peek() >= '0' and self.peek() <= '9' {\n            n = n * 10 + ((self.peek() - '0') as usize)\n            self.pos += 1\n            any = true\n        }\n        return if any { n } else { null }\n    }\n\n    fn parse_atom(self: *mut Self) -> !Node {\n        let c = self.peek()\n        self.pos += 1\n        if c == '(' {\n            var index: i64 = -1\n            if self.peek() == '?' {\n                self.pos += 1\n                if self.peek() != ':' { return error.InvalidInput }\n                self.pos += 1\n            } else {\n                self.ngroups += 1\n                index = self.ngroups as i64\n            }\n            let inner = try self.parse_alt()\n            if self.peek() != ')' { return error.InvalidInput }\n            self.pos += 1\n            return Node.Group(single(inner), index)\n        }\n        if c == ')' or c == '*' or c == '+' or c == '?' { return error.InvalidInput }\n        if c == '[' { return self.parse_class() }\n        if c == '.' { return Node.Any }\n        if c == '^' { return Node.Start }\n        if c == '$' { return Node.End }\n        if c == '\\\\' {\n            if self.eof() { return error.InvalidInput }\n            let e = self.peek()\n            self.pos += 1\n            if e == 'b' { return Node.WordB }\n            if e == 'B' { return Node.NotWordB }\n            if e == 'd' or e == 'w' or e == 's' or e == 'D' or e == 'W' or e == 'S' {\n                var cls = Class{ .negate = e == 'D' or e == 'W' or e == 'S', .ranges = List(u8).new() }\n                add_escape_ranges(&mut cls.ranges, e)\n                self.classes.append(cls)\n                return Node.Cls(self.classes.len - 1)\n            }\n            return Node.Lit(escape_byte(e))\n        }\n        return Node.Lit(c)\n    }\n\n    fn parse_class(self: *mut Self) -> !Node {\n        var cls = Class{ .negate = false, .ranges = List(u8).new() }\n        if self.peek() == '^' {\n            cls.negate = true\n            self.pos += 1\n        }\n        var first = true\n        while true {\n            if self.eof() { return error.InvalidInput }\n            var c = self.peek()\n            if c == ']' and !first { break }\n            first = false\n            self.pos += 1\n            if c == '\\\\' {\n                if self.eof() { return error.InvalidInput }\n                let e = self.peek()\n                self.pos += 1\n                if e == 'd' or e == 'w' or e == 's' {\n                    add_escape_ranges(&mut cls.ranges, e)\n                    continue\n                }\n                c = escape_byte(e)\n            }\n            var hi = c\n            if self.peek() == '-' and self.pos + 1 < self.src.len and self.src[self.pos + 1] != ']' {\n                self.pos += 1\n                hi = self.peek()\n                self.pos += 1\n                if hi == '\\\\' {\n                    if self.eof() { return error.InvalidInput }\n                    hi = escape_byte(self.peek())\n                    self.pos += 1\n                }\n                if hi < c { return error.InvalidInput }\n            }\n            cls.ranges.append(c)\n            cls.ranges.append(hi)\n        }\n        self.pos += 1\n        self.classes.append(cls)\n        return Node.Cls(self.classes.len - 1)\n    }\n}\n\nfn escape_byte(e: u8) -> u8 {\n    if e == 'n' { return '\\n' }\n    if e == 't' { return '\\t' }\n    if e == 'r' { return '\\r' }\n    if e == 'f' { return 12 }\n    if e == 'v' { return 11 }\n    if e == '0' { return 0 }\n    return e\n}\n\nfn add_escape_ranges(r: *mut List(u8), e: u8) {\n    let k: u8 = if e == 'D' { 'd' } else if e == 'W' { 'w' } else if e == 'S' { 's' } else { e }\n    if k == 'd' {\n        r.append('0')\n        r.append('9')\n    } else if k == 'w' {\n        r.append('0')\n        r.append('9')\n        r.append('A')\n        r.append('Z')\n        r.append('a')\n        r.append('z')\n        r.append('_')\n        r.append('_')\n    } else {\n        r.append(' ')\n        r.append(' ')\n        r.append(9)\n        r.append(13)\n    }\n}\n\n// ------------------------------------------------------------------ compiling\n\nfn emit(prog: *mut List(Inst), op: u8, a: usize, b: usize) -> usize {\n    prog.append(Inst{ .op = op, .a = a, .b = b })\n    return prog.len - 1\n}\n\nfn compile_node(n: *Node, prog: *mut List(Inst)) {\n    match n.*{\n        .Empty => { },\n        .Lit(c) => { _ = emit(prog, OP_CHAR, c as usize, 0) },\n        .Any => { _ = emit(prog, OP_ANY, 0, 0) },\n        .Cls(i) => { _ = emit(prog, OP_CLASS, i, 0) },\n        .Start => { _ = emit(prog, OP_START, 0, 0) },\n        .End => { _ = emit(prog, OP_END, 0, 0) },\n        .WordB => { _ = emit(prog, OP_WORDB, 0, 0) },\n        .NotWordB => { _ = emit(prog, OP_NOTWORDB, 0, 0) },\n        .Cat(items) => {\n            for it in items { compile_node(&it, prog) }\n        },\n        .Alt(branches) => {\n            // split L1, L2; L1: a; jmp end; L2: split ... ; last branch; end:\n            var jumps = List(usize).new()\n            for br, i in branches {\n                if i + 1 < branches.len {\n                    let split = emit(prog, OP_SPLIT, 0, 0)\n                    prog[split].a = prog.len\n                    compile_node(&br, prog)\n                    jumps.append(emit(prog, OP_JMP, 0, 0))\n                    prog[split].b = prog.len\n                } else {\n                    compile_node(&br, prog)\n                }\n            }\n            for j in jumps { prog[j].a = prog.len }\n        },\n        .Repeat(inner, min, max, greedy) => {\n            let node = &inner[0]\n            for _ in 0..min { compile_node(node, prog) }\n            if max < 0 {\n                // L1: split L2, L3; L2: node; jmp L1; L3:\n                let split = emit(prog, OP_SPLIT, 0, 0)\n                let body = prog.len\n                compile_node(node, prog)\n                _ = emit(prog, OP_JMP, split, 0)\n                if greedy {\n                    prog[split].a = body\n                    prog[split].b = prog.len\n                } else {\n                    prog[split].a = prog.len\n                    prog[split].b = body\n                }\n            } else {\n                var splits = List(usize).new()\n                for _ in min..max as usize {\n                    let split = emit(prog, OP_SPLIT, 0, 0)\n                    splits.append(split)\n                    let body = prog.len\n                    compile_node(node, prog)\n                    if greedy { prog[split].a = body }\n                    else { prog[split].b = body }\n                }\n                for s in splits {\n                    if greedy { prog[s].b = prog.len }\n                    else { prog[s].a = prog.len }\n                }\n            }\n        },\n        .Group(inner, index) => {\n            if index >= 0 { _ = emit(prog, OP_SAVE, (index as usize) * 2, 0) }\n            compile_node(&inner[0], prog)\n            if index >= 0 { _ = emit(prog, OP_SAVE, (index as usize) * 2 + 1, 0) }\n        },\n    }\n}\n\n/// A compiled pattern.\npub struct Regex {\n    prog: List(Inst)\n    classes: List(Class)\n    ngroups: usize\n    anchored: bool\n}\n\n/// Compile a pattern; `error.InvalidInput` when it is malformed.\npub fn compile(pattern: []u8) -> !Regex {\n    var classes = List(Class).new()\n    var p = Parser{ .src = pattern, .pos = 0, .classes = &mut classes, .ngroups = 0 }\n    let tree = try p.parse_alt()\n    if !p.eof() { return error.InvalidInput }\n    var prog = List(Inst).new()\n    _ = emit(&mut prog, OP_SAVE, 0, 0)\n    compile_node(&tree, &mut prog)\n    _ = emit(&mut prog, OP_SAVE, 1, 0)\n    _ = emit(&mut prog, OP_MATCH, 0, 0)\n    let anchored = pattern.len > 0 and pattern[0] == '^'\n    return Regex{ .prog = prog, .classes = classes, .ngroups = p.ngroups, .anchored = anchored }\n}\n\n/// Does `pattern` match anywhere in `text`? (Compiles every call.)\npub fn is_match(pattern: []u8, text: []u8) -> !bool {\n    let re = try compile(pattern)\n    return re.is_match(text)\n}\n\n// ------------------------------------------------------------------ matching\n\n/// One match: the matched range and the capture groups.\npub struct Match {\n    source: []u8\n    start: usize\n    end: usize\n    // 2 entries per group (0 = whole match); NONE when the group did not take part\n    caps: List(usize)\n}\n\nconst NONE: usize = 0xFFFFFFFFFFFFFFFF\n\nimpl Match {\n    /// The matched bytes.\n    pub fn text(self: *Self) -> []u8 {\n        return self.source[self.start..self.end]\n    }\n\n    /// Group `i` (0 is the whole match); null when the group did not participate.\n    pub fn group(self: *Self, i: usize) -> ?[]u8 {\n        if i * 2 + 1 >= self.caps.len { return null }\n        let s = self.caps[i * 2]\n        let e = self.caps[i * 2 + 1]\n        if s == NONE or e == NONE { return null }\n        return self.source[s..e]\n    }\n\n    /// The number of groups, counting group 0.\n    pub fn group_count(self: *Self) -> usize {\n        return self.caps.len / 2\n    }\n}\n\nstruct Thread {\n    pc: usize\n    caps: List(usize)\n}\n\nstruct Vm {\n    prog: *List(Inst)\n    classes: *List(Class)\n    text: []u8\n    // per-pc generation marks so a pc is added once per step\n    visited: List(usize)\n    gen: usize\n}\n\nfn is_word(c: u8) -> bool {\n    return (c >= '0' and c <= '9') or (c >= 'A' and c <= 'Z') or (c >= 'a' and c <= 'z') or c == '_'\n}\n\nfn class_matches(cls: *Class, c: u8) -> bool {\n    var hit = false\n    var i: usize = 0\n    while i + 1 < cls.ranges.len {\n        if c >= cls.ranges[i] and c <= cls.ranges[i + 1] {\n            hit = true\n            break\n        }\n        i += 2\n    }\n    return hit != cls.negate\n}\n\nimpl Vm {\n    fn add_thread(self: *mut Self, list: *mut List(Thread), pc: usize, own caps: List(usize), pos: usize) {\n        if self.visited[pc] == self.gen { return }\n        self.visited[pc] = self.gen\n        let inst = self.prog[pc]\n        if inst.op == OP_JMP {\n            self.add_thread(list, inst.a, caps, pos)\n        } else if inst.op == OP_SPLIT {\n            self.add_thread(list, inst.a, caps.clone(), pos)\n            self.add_thread(list, inst.b, caps, pos)\n        } else if inst.op == OP_SAVE {\n            var c2 = caps\n            c2[inst.a] = pos\n            self.add_thread(list, pc + 1, c2, pos)\n        } else if inst.op == OP_START {\n            if pos == 0 { self.add_thread(list, pc + 1, caps, pos) }\n        } else if inst.op == OP_END {\n            if pos == self.text.len { self.add_thread(list, pc + 1, caps, pos) }\n        } else if inst.op == OP_WORDB or inst.op == OP_NOTWORDB {\n            let before = pos > 0 and is_word(self.text[pos - 1])\n            let after = pos < self.text.len and is_word(self.text[pos])\n            let at_boundary = before != after\n            if at_boundary == (inst.op == OP_WORDB) { self.add_thread(list, pc + 1, caps, pos) }\n        } else {\n            list.append(Thread{ .pc = pc, .caps = caps })\n        }\n    }\n\n    /// Search from `from`; the leftmost match, with preference by pattern order.\n    fn search(self: *mut Self, from: usize, anchored: bool, ncaps: usize) -> ?List(usize) {\n        var clist = List(Thread).new()\n        var nlist = List(Thread).new()\n        var matched: ?List(usize) = null\n        var pos = from\n        while true {\n            if matched == null and (!anchored or pos == 0) {\n                var fresh = List(usize).with_capacity(ncaps)\n                for _ in 0..ncaps { fresh.append(NONE) }\n                self.gen += 1\n                // keep the marks of threads already in clist for this step\n                self.mark_list(&clist)\n                self.add_thread(&mut clist, 0, fresh, pos)\n            }\n            // no live thread: done once a match exists (or the search is anchored)\n            if clist.len == 0 and (matched != null or anchored) { break }\n            self.gen += 1\n            let c: u8 = if pos < self.text.len { self.text[pos] } else { 0 }\n            var i: usize = 0\n            while i < clist.len {\n                let pc = clist[i].pc\n                let inst = self.prog[pc]\n                var advance = false\n                if inst.op == OP_MATCH {\n                    matched = clist[i].caps.clone()\n                    // lower-priority threads are cut\n                    break\n                } else if pos < self.text.len {\n                    if inst.op == OP_CHAR { advance = c == (inst.a as u8) }\n                    else if inst.op == OP_ANY { advance = c != '\\n' }\n                    else if inst.op == OP_CLASS { advance = class_matches(&self.classes[inst.a], c) }\n                }\n                if advance {\n                    let caps = clist[i].caps.clone()\n                    self.add_thread(&mut nlist, pc + 1, caps, pos + 1)\n                }\n                i += 1\n            }\n            clist.clear()\n            let tmp = clist\n            clist = nlist\n            nlist = tmp\n            if pos >= self.text.len { break }\n            pos += 1\n        }\n        return matched\n    }\n\n    fn mark_list(self: *mut Self, list: *List(Thread)) {\n        for t in list { self.visited[t.pc] = self.gen }\n    }\n}\n\nimpl Regex {\n    fn vm(self: *Self, text: []u8) -> Vm {\n        var visited = List(usize).with_capacity(self.prog.len)\n        for _ in 0..self.prog.len { visited.append(0) }\n        return Vm{ .prog = &self.prog, .classes = &self.classes, .text = text, .visited = visited, .gen = 0 }\n    }\n\n    /// The first match at or after byte `from`.\n    pub fn find_at(self: *Self, text: []u8, from: usize) -> ?Match {\n        if from > text.len { return null }\n        var vm = self.vm(text)\n        let ncaps = (self.ngroups + 1) * 2\n        let caps = vm.search(from, self.anchored, ncaps) orelse return null\n        return Match{ .source = text, .start = caps[0], .end = caps[1], .caps = caps }\n    }\n\n    /// The first match in `text`.\n    pub fn find(self: *Self, text: []u8) -> ?Match {\n        return self.find_at(text, 0)\n    }\n\n    /// Does the pattern match anywhere in `text`?\n    pub fn is_match(self: *Self, text: []u8) -> bool {\n        return self.find_at(text, 0) != null\n    }\n\n    /// Every non-overlapping match, left to right.\n    pub fn find_all(self: *Self, text: []u8) -> List(Match) {\n        var out = List(Match).new()\n        var pos: usize = 0\n        while pos <= text.len {\n            let m = self.find_at(text, pos) orelse break\n            let next = if m.end > m.start { m.end } else { m.end + 1 }\n            out.append(m)\n            pos = next\n            if self.anchored { break }\n        }\n        return out\n    }\n\n    /// Replace every match. In `repl`, `$0`..`$9` insert groups and `$$` is a\n    /// dollar sign.\n    pub fn replace_all(self: *Self, text: []u8, repl: []u8) -> String {\n        var out = String.new()\n        var last: usize = 0\n        for m in self.find_all(text) {\n            out.append(text[last..m.start])\n            expand(&mut out, &m, repl)\n            last = m.end\n        }\n        out.append(text[last..text.len])\n        return out\n    }\n\n    /// The pieces of `text` between matches.\n    pub fn split(self: *Self, text: []u8) -> List([]u8) {\n        var out = List([]u8).new()\n        var last: usize = 0\n        for m in self.find_all(text) {\n            if m.end == m.start { continue }\n            out.append(text[last..m.start])\n            last = m.end\n        }\n        out.append(text[last..text.len])\n        return out\n    }\n}\n\nfn expand(out: *mut String, m: *Match, repl: []u8) {\n    var i: usize = 0\n    while i < repl.len {\n        let c = repl[i]\n        if c == '$' and i + 1 < repl.len {\n            let d = repl[i + 1]\n            if d == '$' {\n                out.push_byte('$')\n                i += 2\n                continue\n            }\n            if d >= '0' and d <= '9' {\n                if let g = m.group((d - '0') as usize) { out.append(g) }\n                i += 2\n                continue\n            }\n        }\n        out.push_byte(c)\n        i += 1\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\nfn found(pattern: []u8, text: []u8) -> ?[]u8 {\n    let re = compile(pattern) catch return null\n    let m = re.find(text) orelse return null\n    return m.text()\n}\n\ntest \"literals, classes and anchors\" {\n    expect_eq(found(\"abc\", \"xxabcxx\").?, \"abc\")\n    expect(found(\"abd\", \"xxabcxx\") == null)\n    expect_eq(found(\"a.c\", \"a\\nc abc\").?, \"abc\")\n    expect_eq(found(\"[0-9]+\", \"ab 4521 x\").?, \"4521\")\n    expect_eq(found(\"[^a-z ]+\", \"abc DEF ghi\").?, \"DEF\")\n    expect_eq(found(\"\\\\d+\\\\.\\\\d+\", \"v 3.14!\").?, \"3.14\")\n    expect_eq(found(\"^\\\\w+\", \"hello world\").?, \"hello\")\n    expect_eq(found(\"\\\\w+$\", \"hello world\").?, \"world\")\n    expect(found(\"^world\", \"hello world\") == null)\n    expect_eq(found(\"\\\\bis\\\\b\", \"this is it\").?, \"is\")\n    expect_eq(found(\"\\\\Bis\\\\b\", \"this is it\").?, \"is\")\n    expect_eq(found(\"[a\\\\-z]+\", \"x-a-z\").?, \"-a-z\")\n    expect_eq(found(\"a\\\\.b\", \"a.b axb\").?, \"a.b\")\n    expect_eq(found(\"\\\\s+\", \"a \\t b\").?, \" \\t \")\n}\n\ntest \"repeats and alternation\" {\n    expect_eq(found(\"ab*c\", \"ac abbbc\").?, \"ac\")\n    expect_eq(found(\"ab+c\", \"ac abbbc\").?, \"abbbc\")\n    expect_eq(found(\"colou?r\", \"the color\").?, \"color\")\n    expect_eq(found(\"a{3}\", \"aa aaaa\").?, \"aaa\")\n    expect_eq(found(\"a{2,}\", \"a aaaa\").?, \"aaaa\")\n    expect_eq(found(\"a{1,2}\", \"aaaa\").?, \"aa\")\n    expect_eq(found(\"cat|dog\", \"hotdog\").?, \"dog\")\n    expect_eq(found(\"(foo|foobar)baz\", \"foobarbaz\").?, \"foobarbaz\")\n    expect_eq(found(\"<.*>\", \"<a><b>\").?, \"<a><b>\")\n    expect_eq(found(\"<.*?>\", \"<a><b>\").?, \"<a>\")\n    expect_eq(found(\"x{2}y\", \"x{2}y xxy\").?, \"xxy\")\n    expect_eq(found(\"a{\", \"a{\").?, \"a{\")\n    expect_eq(found(\"(ab)*c\", \"ababc\").?, \"ababc\")\n    expect_eq(found(\"(a|b)+\", \"cabbad\").?, \"abba\")\n}\n\ntest \"groups and captures\" {\n    let re = try compile(\"(\\\\w+)@(\\\\w+)\\\\.com\")\n    let m = re.find(\"mail bob@example.com now\").?\n    expect_eq(m.text(), \"bob@example.com\")\n    expect_eq(m.start, 5)\n    expect_eq(m.group(1).?, \"bob\")\n    expect_eq(m.group(2).?, \"example\")\n    expect(m.group(3) == null)\n    expect_eq(m.group_count(), 3)\n    let opt = try compile(\"(a)|(b)\")\n    let mb = opt.find(\"b\").?\n    expect(mb.group(1) == null)\n    expect_eq(mb.group(2).?, \"b\")\n    let nc = try compile(\"(?:ab)+(c)\")\n    let mn = nc.find(\"ababc\").?\n    expect_eq(mn.group_count(), 2)\n    expect_eq(mn.group(1).?, \"c\")\n}\n\ntest \"find_all, replace and split\" {\n    let re = try compile(\"\\\\d+\")\n    let all = re.find_all(\"a1 b22 c333\")\n    expect_eq(all.len, 3)\n    expect_eq(all[2].text(), \"333\")\n    expect_eq(re.replace_all(\"a1 b22\", \"<$0>\"), \"a<1> b<22>\")\n    let sw = try compile(\"(\\\\w+) (\\\\w+)\")\n    expect_eq(sw.replace_all(\"hello world\", \"$2 $1\"), \"world hello\")\n    expect_eq(sw.replace_all(\"x y\", \"$$\"), \"$\")\n    let sep = try compile(\",\\\\s*\")\n    let parts = sep.split(\"a, b,c,, d\")\n    expect_eq(parts.len, 5)\n    expect_eq(parts[1], \"b\")\n    expect_eq(parts[3], \"\")\n    let empty = try compile(\"x*\")\n    expect_eq(empty.find_all(\"ab\").len, 3)\n    expect_eq(empty.replace_all(\"ab\", \"-\"), \"-a-b-\")\n}\n\nfn rejects(pattern: []u8) -> bool {\n    _ = compile(pattern) catch |e| { return e == error.InvalidInput }\n    return false\n}\n\ntest \"errors and convenience\" {\n    expect(rejects(\"(\"))\n    expect(rejects(\"a)\"))\n    expect(rejects(\"[a\"))\n    expect(rejects(\"a{3,1}\"))\n    expect(rejects(\"*a\"))\n    expect(rejects(\"[z-a]\"))\n    expect(!rejects(\"a{\"))\n    expect(try is_match(\"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"2026-09-19\"))\n    expect(! (try is_match(\"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"2026-9-19\")))\n}\n";
static const char nx_str_1306[7] = "stream";
static const char nx_str_1307[8433] = "// std.stream: buffered readers and writers over files and the standard\n// streams, written in Nexium.\n//\n// `import std.stream` then:\n//\n//     var r = try stream.Reader.open(\"big.log\")\n//     while true {                                    // no whole-file allocation\n//         let line = (try r.read_line()) orelse break\n//         ...\n//     }\n//     r.close()\n//\n//     var w = try stream.Writer.open(\"out.txt\")\n//     try w.write_line(\"hello\")\n//     try w.close()                                    // flushes, then closes\n//\n//     var input = stream.Reader.stdin()\n//     var out = stream.Writer.stdout()\n//     try stream.copy(&mut input, &mut out)\n//     try out.flush()\n//\n// Readers buffer 64 KB at a time; writers gather output and flush when the\n// buffer fills, on `flush`, and on `close`. A Writer must be flushed or\n// closed before the program ends, or buffered output is lost.\n\npub const STDIN: i64 = 1\npub const STDOUT: i64 = 2\npub const STDERR: i64 = 3\n\nconst CHUNK: usize = 65536\n\n/// Reads a handle through a buffer.\npub struct Reader {\n    handle: i64\n    buf: String\n    pos: usize\n    eof: bool\n    owns: bool\n    socket: bool\n}\n\nimpl Reader {\n    /// Open a file for reading.\n    pub fn open(path: []u8) -> !Reader {\n        let h = try io.open(path, \"r\")\n        return Reader{ .handle = h, .buf = String.new(), .pos = 0, .eof = false, .owns = true, .socket = false }\n    }\n\n    /// Standard input.\n    pub fn stdin() -> Reader {\n        return Reader{ .handle = STDIN, .buf = String.new(), .pos = 0, .eof = false, .owns = false, .socket = false }\n    }\n\n    /// Wrap a handle from `io.open`; `close` will not close it.\n    pub fn from_handle(handle: i64) -> Reader {\n        return Reader{ .handle = handle, .buf = String.new(), .pos = 0, .eof = false, .owns = false, .socket = false }\n    }\n\n    /// Wrap a connected socket from `net.connect` or `net.accept`; `close`\n    /// will not close it.\n    pub fn from_socket(sock: i64) -> Reader {\n        return Reader{ .handle = sock, .buf = String.new(), .pos = 0, .eof = false, .owns = false, .socket = true }\n    }\n\n    fn pull(self: *mut Self, n: usize) -> !String {\n        if self.socket { return net.recv(self.handle, n, 0) }\n        return io.read(self.handle, n)\n    }\n\n    // Drop consumed bytes and pull in the next chunk; false at end of input.\n    fn fill(self: *mut Self) -> !bool {\n        if self.eof { return false }\n        if self.pos > 0 {\n            let rest = String.from(self.buf[self.pos..self.buf.len])\n            self.buf = rest\n            self.pos = 0\n        }\n        let chunk = try self.pull(CHUNK)\n        if chunk.len == 0 {\n            self.eof = true\n            return false\n        }\n        self.buf.append(chunk)\n        return true\n    }\n\n    /// The next line without its `\\n` (or `\\r\\n`); null at end of input.\n    pub fn read_line(self: *mut Self) -> !?String {\n        while true {\n            var i = self.pos\n            while i < self.buf.len and self.buf[i] != '\\n' { i += 1 }\n            if i < self.buf.len {\n                var end = i\n                if end > self.pos and self.buf[end - 1] == '\\r' { end -= 1 }\n                let line = String.from(self.buf[self.pos..end])\n                self.pos = i + 1\n                return line\n            }\n            if ! (try self.fill()) {\n                if self.pos < self.buf.len {\n                    var end = self.buf.len\n                    if self.buf[end - 1] == '\\r' { end -= 1 }\n                    let line = String.from(self.buf[self.pos..end])\n                    self.pos = self.buf.len\n                    return line\n                }\n                return null\n            }\n        }\n    }\n\n    /// Up to `n` bytes; empty at end of input.\n    pub fn read(self: *mut Self, n: usize) -> !String {\n        if self.pos >= self.buf.len {\n            if ! (try self.fill()) { return String.new() }\n        }\n        var end = self.pos + n\n        if end > self.buf.len { end = self.buf.len }\n        let out = String.from(self.buf[self.pos..end])\n        self.pos = end\n        return out\n    }\n\n    /// Everything that is left.\n    pub fn read_all(self: *mut Self) -> !String {\n        var out = String.from(self.buf[self.pos..self.buf.len])\n        self.pos = self.buf.len\n        while !self.eof {\n            let chunk = try self.pull(CHUNK)\n            if chunk.len == 0 { break }\n            out.append(chunk)\n        }\n        self.eof = true\n        return out\n    }\n\n    /// Release the file (the standard streams stay open).\n    pub fn close(self: *mut Self) {\n        if self.owns {\n            io.close(self.handle) catch { }\n            self.owns = false\n        }\n        self.eof = true\n    }\n}\n\n/// Buffers output to a handle.\npub struct Writer {\n    handle: i64\n    buf: String\n    owns: bool\n    socket: bool\n}\n\nimpl Writer {\n    /// Create or replace a file.\n    pub fn open(path: []u8) -> !Writer {\n        let h = try io.open(path, \"w\")\n        return Writer{ .handle = h, .buf = String.new(), .owns = true, .socket = false }\n    }\n\n    /// Open a file for appending.\n    pub fn append(path: []u8) -> !Writer {\n        let h = try io.open(path, \"a\")\n        return Writer{ .handle = h, .buf = String.new(), .owns = true, .socket = false }\n    }\n\n    pub fn stdout() -> Writer {\n        return Writer{ .handle = STDOUT, .buf = String.new(), .owns = false, .socket = false }\n    }\n\n    pub fn stderr() -> Writer {\n        return Writer{ .handle = STDERR, .buf = String.new(), .owns = false, .socket = false }\n    }\n\n    /// Wrap a handle from `io.open`; `close` will not close it.\n    pub fn from_handle(handle: i64) -> Writer {\n        return Writer{ .handle = handle, .buf = String.new(), .owns = false, .socket = false }\n    }\n\n    /// Wrap a connected socket; `close` will not close it.\n    pub fn from_socket(sock: i64) -> Writer {\n        return Writer{ .handle = sock, .buf = String.new(), .owns = false, .socket = true }\n    }\n\n    pub fn write(self: *mut Self, data: []u8) -> !void {\n        self.buf.append(data)\n        if self.buf.len >= CHUNK { try self.flush() }\n    }\n\n    pub fn write_line(self: *mut Self, data: []u8) -> !void {\n        try self.write(data)\n        return self.write(\"\\n\")\n    }\n\n    /// Hand buffered output to the handle.\n    pub fn flush(self: *mut Self) -> !void {\n        if self.buf.len > 0 {\n            if self.socket { try net.send(self.handle, self.buf) }\n            else { try io.write(self.handle, self.buf) }\n            self.buf.clear()\n        }\n        if !self.socket { return io.flush(self.handle) }\n    }\n\n    /// Flush, then release the file (the standard streams stay open).\n    pub fn close(self: *mut Self) -> !void {\n        try self.flush()\n        if self.owns {\n            self.owns = false\n            return io.close(self.handle)\n        }\n    }\n}\n\n/// Copy everything from a reader to a writer; the number of bytes moved.\npub fn copy(r: *mut Reader, w: *mut Writer) -> !usize {\n    var total: usize = 0\n    while true {\n        let chunk = try r.read(CHUNK)\n        if chunk.len == 0 { break }\n        try w.write(chunk)\n        total += chunk.len\n    }\n    return total\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"lines and chunks\" {\n    let dir = io.temp_dir()\n    var path = String.from(dir)\n    path.append(\"/nxstream-test.txt\")\n    var w = try Writer.open(path)\n    try w.write_line(\"first\")\n    try w.write(\"second\\r\\n\")\n    try w.write(\"third\")\n    try w.close()\n\n    var r = try Reader.open(path)\n    expect_eq((try r.read_line()).?, \"first\")\n    expect_eq((try r.read_line()).?, \"second\")\n    expect_eq((try r.read_line()).?, \"third\")\n    expect(try r.read_line() == null)\n    r.close()\n\n    var r2 = try Reader.open(path)\n    expect_eq(try r2.read(3), \"fir\")\n    expect_eq(try r2.read_all(), \"st\\nsecond\\r\\nthird\")\n    r2.close()\n\n    var copy_path = String.from(dir)\n    copy_path.append(\"/nxstream-copy.txt\")\n    var src = try Reader.open(path)\n    var dst = try Writer.open(copy_path)\n    expect_eq(try copy(&mut src, &mut dst), 19)\n    try dst.close()\n    src.close()\n    expect_eq(try io.read_file(copy_path), \"first\\nsecond\\r\\nthird\")\n    try io.remove_file(path)\n    try io.remove_file(copy_path)\n}\n\ntest \"missing file\" {\n    var missing = false\n    _ = Reader.open(\"definitely/not/here.txt\") catch |e| {\n        missing = e == error.NotFound\n        Reader.stdin()\n    }\n    expect(missing)\n}\n";
